-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 100 recettes, 5 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"sellou-ma","country":"MA","original":"Sellou","title":"Sellou (poudre marocaine aux graines et amandes)","en":"Sellou (Moroccan toasted flour and nut sweet)","es":"Sellou (dulce marroquí de harina y frutos secos)","desc":"Préparation marocaine de farine grillée, sésame et amandes, liée au miel et au beurre; servie en poudre ou tassée.","cat":"Dessert","diff":"medium","prep":25,"cook":25,"serv":12,"reference":"https://en.wikipedia.org/wiki/Sellou","auth":"adapted","ing":[["Farine",250,"g",null],["Sésame",180,"g",null],["Amandes",150,"g",null],["Beurre",120,"g",null],["Miel",100,"g",null],["Sucre glace",60,"g",null],["Cannelle",1,"c. à thé",null],["Anis moulu",0.5,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Étaler la farine dans un plat et la griller à 170 °C environ 25 minutes, en remuant toutes les 5 minutes, jusqu’à couleur noisette uniforme.","Griller séparément sésame et amandes à la poêle sèche; laisser tiédir. Réserver quelques amandes pour décorer.","Mixer les graines et les amandes par impulsions pour obtenir une poudre, sans les transformer entièrement en pâte.","Mélanger avec farine refroidie, sucre, cannelle, anis et sel. Incorporer beurre fondu puis miel.","Émietter à la main ou tasser dans de petits bols. Laisser refroidir avant de servir; conserver au frais dans un contenant fermé."],"photo":{"file":"File:Sellou.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Sellou.JPG/500px-Sellou.JPG","page":"https://commons.wikimedia.org/wiki/File:Sellou.JPG","author":"Lucyin","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"briouat-ma","country":"MA","original":"Briouat","title":"Briouates aux amandes et miel","en":"Almond and honey briouats","es":"Briouats de almendras y miel","desc":"Petits triangles marocains de pâte fine, farcis aux amandes et plongés dans le miel.","cat":"Dessert","diff":"medium","prep":35,"cook":15,"serv":12,"reference":"https://en.wikipedia.org/wiki/Briouat","auth":"adapted","ing":[["Feuilles de brick",6,null,null],["Amandes mondées",200,"g",null],["Sucre",60,"g",null],["Beurre",25,"g",null],["Eau de fleur d’oranger",1,"c. à soupe",null],["Cannelle",0.5,"c. à thé",null],["Miel",180,"g",null],["Huile de friture",600,"ml",null],["Farine",1,"c. à soupe",null],["Eau",1,"c. à soupe",null]],"steps":["Mixer les amandes avec le sucre, puis incorporer beurre ramolli, fleur d’oranger et cannelle. Former 12 portions.","Couper chaque feuille de brick en deux bandes. Mélanger farine et eau pour obtenir une colle alimentaire.","Déposer une portion de farce au bout d’une bande, puis replier en triangle jusqu’au bout; fermer avec la colle.","Frire à 170 °C par petites fournées 3 à 4 minutes, en retournant, jusqu’à pâte croustillante et dorée.","Égoutter puis tremper brièvement dans le miel tiédi. Laisser reposer sur une grille avant de servir."],"photo":{"file":"File:Moroccan food-02.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Moroccan_food-02.jpg/500px-Moroccan_food-02.jpg","page":"https://commons.wikimedia.org/wiki/File:Moroccan_food-02.jpg","author":"Christian Muise","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"batbout-ma","country":"MA","original":"Batbout","title":"Batbout (petits pains marocains à la poêle)","en":"Batbout (Moroccan skillet breads)","es":"Batbout (panes marroquíes a la sartén)","desc":"Pains marocains ronds à la farine et semoule fine, cuits à la poêle plutôt qu’au four.","cat":"Pain","diff":"medium","prep":25,"cook":15,"serv":8,"reference":"https://en.wikipedia.org/wiki/Batbout","auth":"adapted","ing":[["Farine",250,"g",null],["Semoule très fine",150,"g",null],["Eau tiède",250,"ml",null],["Levure sèche",5,"g",null],["Sel",1,"c. à thé",null],["Sucre",1,"c. à thé",null]],"steps":["Mélanger farine, semoule, levure, sucre et sel. Ajouter progressivement l’eau tiède et pétrir 10 minutes jusqu’à pâte souple.","Couvrir et laisser lever environ 1 heure, jusqu’à augmentation nette de volume.","Diviser en 8 boules. Abaisser chacune à 1/4 pouce sur un plan légèrement semoulé; couvrir et laisser reposer 20 minutes.","Cuire dans une poêle sèche à feu moyen 3 à 4 minutes par face; retourner plusieurs fois si nécessaire pour éviter de brûler.","Les pains doivent être gonflés et cuits à cœur. Les envelopper dans un linge propre pour conserver leur souplesse."],"photo":{"file":"File:Batbout.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Batbout.jpg/500px-Batbout.jpg","page":"https://commons.wikimedia.org/wiki/File:Batbout.jpg","author":"مصطفى ملو","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"kesra-dz","country":"DZ","original":"Kesra","title":"Kesra (galette algérienne de semoule)","en":"Kesra (Algerian semolina flatbread)","es":"Kesra (pan plano argelino de sémola)","desc":"Galette algérienne de semoule, huile et eau, cuite sur une plaque ou une poêle épaisse.","cat":"Pain","diff":"easy","prep":20,"cook":20,"serv":6,"reference":"https://en.wikipedia.org/wiki/Kesra","auth":"adapted","ing":[["Semoule moyenne",400,"g",null],["Huile d’olive",60,"ml",null],["Eau",190,"ml",null],["Sel",1,"c. à thé",null],["Graines de nigelle",1,"c. à thé",null]],"steps":["Mélanger semoule, sel et nigelle. Frotter l’huile entre les grains pour la répartir uniformément.","Ajouter l’eau progressivement et rassembler sans long pétrissage. Laisser reposer 10 minutes pour hydrater la semoule.","Diviser en deux galettes rondes d’environ 1/2 pouce; piquer leur surface à la fourchette.","Cuire dans une poêle épaisse à feu moyen doux 8 à 10 minutes par face, jusqu’à coloration dorée et centre cuit.","Laisser tiédir puis couper en pointes. Servir avec soupe, huile d’olive ou accompagnement de son choix."],"photo":{"file":"File:Kesra algérienne (pain maghrébin).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Kesra_alg%C3%A9rienne_%28pain_maghr%C3%A9bin%29.jpg/500px-Kesra_alg%C3%A9rienne_%28pain_maghr%C3%A9bin%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Kesra_alg%C3%A9rienne_(pain_maghr%C3%A9bin).jpg","author":"Indif","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"slata-mechouia-tn","country":"TN","original":"Slata mechouia","title":"Slata mechouia (salade tunisienne grillée)","en":"Slata mechouia (Tunisian grilled pepper salad)","es":"Slata mechouia (ensalada tunecina de verduras asadas)","desc":"Salade tunisienne de poivrons et tomates grillés, hachés puis assaisonnés; thon et œufs proposés en garniture.","cat":"Salade","diff":"easy","prep":25,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Slata_mechouia","auth":"adapted","ing":[["Poivrons verts",4,null,null],["Tomates",3,null,null],["Ail",3,"gousses",null],["Huile d’olive",3,"c. à soupe",null],["Jus de citron",1,"c. à soupe",null],["Carvi moulu",0.5,"c. à thé",null],["Sel",0.5,"c. à thé",null],["Thon égoutté",100,"g","facultatif"],["Œufs",2,null,"facultatifs"],["Olives",60,"g","facultatives"]],"steps":["Griller poivrons, tomates et ail sous le gril du four, en retournant, jusqu’à peau cloquée; compter 20 à 25 minutes.","Couvrir les poivrons 10 minutes dans un bol, puis peler et épépiner. Peler les tomates et retirer l’excès d’eau.","Hacher les légumes au couteau, sans les réduire en purée. Écraser l’ail cuit.","Mélanger avec huile, citron, carvi et sel. Laisser reposer 20 minutes pour unir les saveurs.","Servir seule ou avec thon, olives et quartiers d’œufs cuits durs 10 minutes."],"photo":{"file":"File:سلاطة مشوية، مع الزيتون الاخضر، تونس 2020.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/%D8%B3%D9%84%D8%A7%D8%B7%D8%A9_%D9%85%D8%B4%D9%88%D9%8A%D8%A9%D8%8C_%D9%85%D8%B9_%D8%A7%D9%84%D8%B2%D9%8A%D8%AA%D9%88%D9%86_%D8%A7%D9%84%D8%A7%D8%AE%D8%B6%D8%B1%D8%8C_%D8%AA%D9%88%D9%86%D8%B3_2020.jpg/500px-%D8%B3%D9%84%D8%A7%D8%B7%D8%A9_%D9%85%D8%B4%D9%88%D9%8A%D8%A9%D8%8C_%D9%85%D8%B9_%D8%A7%D9%84%D8%B2%D9%8A%D8%AA%D9%88%D9%86_%D8%A7%D9%84%D8%A7%D8%AE%D8%B6%D8%B1%D8%8C_%D8%AA%D9%88%D9%86%D8%B3_2020.jpg","page":"https://commons.wikimedia.org/wiki/File:%D8%B3%D9%84%D8%A7%D8%B7%D8%A9_%D9%85%D8%B4%D9%88%D9%8A%D8%A9%D8%8C_%D9%85%D8%B9_%D8%A7%D9%84%D8%B2%D9%8A%D8%AA%D9%88%D9%86_%D8%A7%D9%84%D8%A7%D8%AE%D8%B6%D8%B1%D8%8C_%D8%AA%D9%88%D9%86%D8%B3_2020.jpg","author":"Habib M'henni","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"bsissa-tn","country":"TN","original":"Bsissa","title":"Bsissa (préparation tunisienne grillée)","en":"Bsissa (Tunisian roasted cereal mixture)","es":"Bsissa (mezcla tunecina de cereales tostados)","desc":"Adaptation domestique de la bsissa tunisienne avec farine de blé et pois chiches grillée, épices et huile d’olive.","cat":"Dessert","diff":"easy","prep":15,"cook":25,"serv":8,"reference":"https://en.wikipedia.org/wiki/Bsissa","auth":"adapted","ing":[["Farine de blé",200,"g",null],["Farine de pois chiches",100,"g",null],["Huile d’olive",100,"ml",null],["Sucre",60,"g",null],["Coriandre moulue",1,"c. à thé",null],["Anis moulu",0.5,"c. à thé",null],["Fenouil moulu",0.5,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Étaler les farines dans un plat et griller à 160 °C 20 à 25 minutes, en remuant souvent, jusqu’à parfum grillé et teinte beige.","Ajouter les épices pendant les 3 dernières minutes, sans les laisser brûler.","Laisser refroidir complètement puis tamiser pour enlever les grumeaux. Incorporer sucre et sel.","Ajouter l’huile progressivement en remuant; arrêter lorsque la préparation se rassemble en pâte épaisse.","Servir en petites portions. Conserver au frais; la version sèche peut aussi être gardée séparément et liée au moment de servir."],"photo":{"file":"File:Bsissa 03.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Bsissa_03.JPG/500px-Bsissa_03.JPG","page":"https://commons.wikimedia.org/wiki/File:Bsissa_03.JPG","author":"Yamen","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"mloukhia-tn","country":"TN","original":"Mloukhia","title":"Mloukhia tunisienne au bœuf","en":"Tunisian beef mloukhia","es":"Mloukhia tunecina de ternera","desc":"Mijoté tunisien sombre à la poudre de feuilles de corète et au bœuf. Cette version diffère de la soupe égyptienne de feuilles fraîches.","cat":"Plat principal","diff":"medium","prep":20,"cook":240,"serv":6,"reference":"https://en.wikipedia.org/wiki/Mloukhia","auth":"adapted","ing":[["Bœuf à braiser",900,"g",null],["Poudre de mloukhia",80,"g",null],["Huile d’olive",150,"ml",null],["Eau chaude",2200,"ml",null],["Ail",5,"gousses",null],["Coriandre moulue",1,"c. à thé",null],["Carvi",1,"c. à thé",null],["Harissa",1,"c. à soupe",null],["Laurier",2,"feuilles",null],["Sel",1,"c. à thé",null]],"steps":["Dans une grande cocotte hors du feu, mélanger poudre de corète et huile jusqu’à pâte lisse.","Verser l’eau chaude très progressivement en fouettant. Porter au frémissement puis cuire à feu très doux 2 heures, partiellement couvert.","Ajouter bœuf en gros cubes, ail écrasé, harissa, coriandre, carvi, laurier et sel.","Poursuivre le mijotage environ 2 heures, en remuant régulièrement, jusqu’à viande très tendre et sauce sombre lisse; ajouter de l’eau au besoin.","Retirer le laurier, rectifier l’assaisonnement et laisser reposer 15 minutes. Servir avec du pain."],"photo":{"file":"File:Mloukhia.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Mloukhia.jpg/500px-Mloukhia.jpg","page":"https://commons.wikimedia.org/wiki/File:Mloukhia.jpg","author":"Meriemou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"mbakbaka-ly","country":"LY","original":"Mbakbaka","title":"Mbakbaka (pâtes libyennes à la tomate et au poulet)","en":"Mbakbaka (Libyan tomato chicken pasta)","es":"Mbakbaka (pasta libia con tomate y pollo)","desc":"Pâtes libyennes cuites directement dans un bouillon épicé à la tomate; adaptation au poulet.","cat":"Plat principal","diff":"easy","prep":20,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Mbakbaka","auth":"adapted","ing":[["Poulet désossé",500,"g",null],["Pâtes courtes",300,"g",null],["Tomates concassées",400,"g",null],["Concentré de tomate",2,"c. à soupe",null],["Oignon",1,null,null],["Ail",3,"gousses",null],["Bouillon",1000,"ml",null],["Huile",2,"c. à soupe",null],["Paprika",1,"c. à thé",null],["Curcuma",0.5,"c. à thé",null],["Piment",0.25,"c. à thé",null],["Sel",0.5,"c. à thé",null]],"steps":["Couper le poulet en morceaux de 1 pouce. Faire revenir l’oignon haché dans l’huile 5 minutes.","Ajouter poulet, ail, épices et concentré. Remuer 3 minutes pour développer les arômes.","Verser tomates et bouillon, puis mijoter 15 minutes, jusqu’à poulet cuit.","Ajouter les pâtes et cuire 10 à 12 minutes, en remuant souvent; compléter avec un peu d’eau si elles absorbent tout le liquide.","Vérifier que les pâtes sont tendres et le poulet atteint 74 °C. Servir bien chaud avec un peu de bouillon."],"photo":{"file":"File:مبكبكة Mbakbaka (Las Siete Orillas project).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/%D9%85%D8%A8%D9%83%D8%A8%D9%83%D8%A9_Mbakbaka_%28Las_Siete_Orillas_project%29.jpg/500px-%D9%85%D8%A8%D9%83%D8%A8%D9%83%D8%A9_Mbakbaka_%28Las_Siete_Orillas_project%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%D9%85%D8%A8%D9%83%D8%A8%D9%83%D8%A9_Mbakbaka_(Las_Siete_Orillas_project).jpg","author":"El Mono Español","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"kontomire-stew-gh","country":"GH","original":"Kontomire stew","title":"Kontomire (ragoût ghanéen de feuilles et graines)","en":"Kontomire stew (Ghanaian greens and seed stew)","es":"Kontomire (guiso ghanés de hojas y semillas)","desc":"Adaptation du ragoût ghanéen de feuilles de taro avec épinards, egusi et maquereau fumé.","cat":"Plat principal","diff":"medium","prep":20,"cook":35,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kontomire_stew","auth":"adapted","ing":[["Épinards",500,"g","substitution domestique des feuilles de taro"],["Graines egusi moulues",100,"g",null],["Maquereau fumé",200,"g",null],["Tomates",3,null,null],["Oignon",1,null,null],["Huile de palme alimentaire",3,"c. à soupe",null],["Eau",200,"ml",null],["Piment",1,null,null],["Sel",0.5,"c. à thé",null]],"steps":["Laver les épinards et les hacher. Émietter le poisson en retirant soigneusement les arêtes.","Cuire l’oignon haché dans l’huile 5 minutes. Ajouter tomates en dés et piment, puis laisser compoter 10 minutes.","Mélanger les graines egusi avec 100 ml d’eau. Déposer des cuillerées dans la sauce et couvrir 8 minutes avant de remuer doucement.","Ajouter épinards, poisson et reste d’eau; mijoter 8 à 10 minutes jusqu’à feuilles cuites et sauce liée.","Saler après avoir goûté le poisson. Servir avec igname, plantain ou riz cuits."],"photo":{"file":"File:Plantain and kontomire stew with pear and koobi(smoked tilapia)..jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/02/Plantain_and_kontomire_stew_with_pear_and_koobi%28smoked_tilapia%29..jpg","page":"https://commons.wikimedia.org/wiki/File:Plantain_and_kontomire_stew_with_pear_and_koobi(smoked_tilapia)..jpg","author":"Isaacvysions","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"efo-riro-ng","country":"NG","original":"Efo riro","title":"Efo riro (ragoût nigérian de légumes feuillus)","en":"Efo riro (Nigerian leafy green stew)","es":"Efo riro (guiso nigeriano de verduras de hoja)","desc":"Ragoût nigérian de légumes verts dans une sauce aux poivrons, tomates et huile de palme; adaptation au bœuf et épinards.","cat":"Plat principal","diff":"medium","prep":25,"cook":80,"serv":4,"reference":"https://en.wikipedia.org/wiki/Efo_riro","auth":"adapted","ing":[["Bœuf à braiser",500,"g",null],["Épinards",600,"g",null],["Poivrons rouges",2,null,null],["Tomates",3,null,null],["Oignons",2,null,null],["Huile de palme alimentaire",60,"ml",null],["Poisson fumé",100,"g",null],["Piment",1,null,null],["Bouillon",400,"ml",null],["Sel",0.5,"c. à thé",null]],"steps":["Mijoter le bœuf en cubes avec un oignon haché et le bouillon 50 à 60 minutes, jusqu’à tendreté.","Mixer grossièrement poivrons, tomates et piment. Cuire cette purée 10 minutes dans une casserole pour concentrer son eau.","Chauffer l’huile doucement et faire revenir le second oignon 5 minutes. Ajouter la purée et cuire 10 minutes.","Incorporer bœuf, 150 ml de son bouillon et poisson fumé sans arêtes; laisser frémir 5 minutes.","Ajouter les épinards hachés, cuire 5 à 8 minutes, goûter et saler. La sauce doit enrober les feuilles sans être très liquide."],"photo":{"file":"File:Efo riro and pounded yam.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Efo_riro_and_pounded_yam.jpg/500px-Efo_riro_and_pounded_yam.jpg","page":"https://commons.wikimedia.org/wiki/File:Efo_riro_and_pounded_yam.jpg","author":"Atimukoh","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"edikang-ikong-ng","country":"NG","original":"Edikang ikong","title":"Edikang ikong (ragoût nigérian de feuilles)","en":"Edikang ikong (Nigerian leafy vegetable soup)","es":"Edikang ikong (guiso nigeriano de hojas)","desc":"Adaptation domestique du ragoût efik de feuilles avec épinards et feuilles de courge, viande et poisson fumé.","cat":"Plat principal","diff":"medium","prep":25,"cook":75,"serv":4,"reference":"https://en.wikipedia.org/wiki/Edikang_ikong","auth":"adapted","ing":[["Bœuf à braiser",500,"g",null],["Épinards",400,"g",null],["Feuilles de courge",300,"g","remplaçables par bette"],["Poisson fumé",150,"g",null],["Écrevisses séchées moulues",2,"c. à soupe",null],["Huile de palme alimentaire",60,"ml",null],["Oignon",1,null,null],["Bouillon",400,"ml",null],["Piment",1,null,null],["Sel",0.5,"c. à thé",null]],"steps":["Faire mijoter le bœuf avec oignon et bouillon 50 à 60 minutes, jusqu’à tendreté; garder un fond de liquide.","Laver et hacher séparément les feuilles. Retirer les arêtes du poisson fumé.","Ajouter au bœuf poisson, écrevisses, piment et huile de palme, puis frémir 5 minutes.","Incorporer d’abord les feuilles de courge ou bette; cuire 5 minutes. Ajouter les épinards et poursuivre 5 minutes.","Goûter avant de saler. Servir ce ragoût épais avec une pâte de céréales ou du riz."],"photo":{"file":"File:Edikaikong.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/a/a3/Edikaikong.JPG","page":"https://commons.wikimedia.org/wiki/File:Edikaikong.JPG","author":"Nne75","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"kachumbari-ke","country":"KE","original":"Kachumbari","title":"Kachumbari (salade fraîche d’Afrique de l’Est)","en":"Kachumbari (East African fresh salad)","es":"Kachumbari (ensalada fresca de África oriental)","desc":"Salade de tomate, oignon et piment courante au Kenya et dans d’autres pays d’Afrique de l’Est; pas d’origine urbaine exclusive attribuée.","cat":"Salade","diff":"easy","prep":15,"cook":0,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kachumbari","auth":"adapted","ing":[["Tomates",4,null,null],["Oignon rouge",1,null,null],["Concombre",0.5,null,null],["Jus de lime",2,"c. à soupe",null],["Coriandre fraîche",15,"g",null],["Piment vert",1,null,null],["Sel",0.5,"c. à thé",null]],"steps":["Émincer l’oignon et le tremper dans l’eau froide 10 minutes pour atténuer son piquant, puis bien l’égoutter.","Couper tomates et concombre en petits dés, en conservant un peu du jus des tomates.","Épépiner le piment si une salade douce est souhaitée; le hacher avec la coriandre.","Mélanger les légumes avec lime et sel. Laisser reposer 10 minutes au frais.","Goûter et servir le jour même, notamment avec viande grillée, riz ou ugali."],"photo":{"file":"File:Kachumbari.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/96/Kachumbari.jpg","page":"https://commons.wikimedia.org/wiki/File:Kachumbari.jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"hertzoggies-za","country":"ZA","original":"Hertzoggies","title":"Hertzoggies (tartelettes sud-africaines à la confiture)","en":"Hertzoggies (South African coconut jam tartlets)","es":"Hertzoggies (tartaletas sudafricanas de coco y mermelada)","desc":"Tartelettes sud-africaines garnies de confiture d’abricot et d’une meringue à la noix de coco.","cat":"Dessert","diff":"medium","prep":30,"cook":25,"serv":12,"reference":"https://en.wikipedia.org/wiki/Hertzoggie","auth":"adapted","ing":[["Farine",200,"g",null],["Beurre",100,"g",null],["Sucre",50,"g",null],["Jaunes d’œufs",2,null,null],["Eau froide",2,"c. à soupe",null],["Confiture d’abricot",150,"g",null],["Blancs d’œufs",2,null,null],["Sucre fin",100,"g",null],["Noix de coco râpée",100,"g",null],["Sel",0.25,"c. à thé",null]],"steps":["Sabler farine, sel et beurre froid. Ajouter sucre, jaunes et eau pour rassembler la pâte; réfrigérer 30 minutes.","Abaisser à 1/8 pouce, découper 12 disques et foncer un moule à muffins légèrement beurré.","Déposer une petite cuillère de confiture dans chaque fond, en laissant de la place pour la meringue.","Monter les blancs en neige puis ajouter progressivement le sucre fin. Incorporer délicatement la noix de coco.","Couvrir la confiture de meringue et cuire à 180 °C 20 à 25 minutes, jusqu’à pâte dorée et dessus légèrement coloré. Laisser tiédir avant de démouler."],"photo":{"file":"File:Hertzoggies for sale in a Cape Town bakery (22 July 2016).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Hertzoggies_for_sale_in_a_Cape_Town_bakery_%2822_July_2016%29.jpg/500px-Hertzoggies_for_sale_in_a_Cape_Town_bakery_%2822_July_2016%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Hertzoggies_for_sale_in_a_Cape_Town_bakery_(22_July_2016).jpg","author":"Discott","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"vanilla-slice-au","country":"AU","original":"Vanilla slice","title":"Vanilla slice (millefeuille australien à la crème)","en":"Vanilla slice (Australian custard slice)","es":"Vanilla slice (milhojas australiano de crema)","desc":"Carrés australiens de crème pâtissière ferme entre deux couches de pâte feuilletée, avec glaçage simple.","cat":"Dessert","diff":"medium","prep":35,"cook":25,"serv":9,"reference":"https://en.wikipedia.org/wiki/Vanilla_slice","auth":"adapted","ing":[["Pâte feuilletée",400,"g",null],["Lait",600,"ml",null],["Crème 35 %",200,"ml",null],["Sucre",120,"g",null],["Fécule de maïs",70,"g",null],["Jaunes d’œufs",4,null,null],["Vanille",2,"c. à thé",null],["Beurre",30,"g",null],["Sucre glace",150,"g",null],["Eau",2,"c. à soupe",null]],"steps":["Abaisser la pâte en deux carrés de 8 pouces, piquer et cuire à 200 °C 20 à 25 minutes sous une seconde plaque pour limiter le gonflement.","Fouetter jaunes, sucre et fécule avec 150 ml de lait froid. Chauffer le lait restant et la crème.","Verser progressivement le liquide chaud sur les jaunes, remettre dans la casserole et cuire en remuant jusqu’à ébullition; poursuivre 1 minute.","Ajouter beurre et vanille. Déposer un carré de pâte dans un moule chemisé de 8 pouces, couvrir de crème puis de la seconde pâte.","Réfrigérer 6 heures. Mélanger sucre glace et eau, glacer le dessus et découper délicatement en 9 portions avec un couteau dentelé."],"photo":{"file":"File:Aussie vanilla slice.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Aussie_vanilla_slice.jpg/500px-Aussie_vanilla_slice.jpg","page":"https://commons.wikimedia.org/wiki/File:Aussie_vanilla_slice.jpg","author":"Finbar.concaig","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chocolate-crackles-au","country":"AU","original":"Chocolate crackles","title":"Chocolate crackles (bouchées australiennes au riz soufflé)","en":"Chocolate crackles (Australian puffed rice treats)","es":"Chocolate crackles (bocados australianos de arroz inflado)","desc":"Bouchées australiennes sans cuisson au riz soufflé, cacao, coco et graisse de coco solidifiée.","cat":"Dessert","diff":"easy","prep":15,"cook":5,"serv":12,"reference":"https://en.wikipedia.org/wiki/Chocolate_crackles","auth":"adapted","ing":[["Riz soufflé",100,"g",null],["Sucre glace",120,"g",null],["Noix de coco râpée",80,"g",null],["Cacao",25,"g",null],["Huile de coco solide",150,"g",null]],"steps":["Disposer 12 caissettes dans un moule à muffins. Mélanger riz soufflé, sucre glace tamisé, coco et cacao.","Faire fondre doucement l’huile de coco, puis laisser tiédir pour qu’elle reste liquide sans être brûlante.","La verser sur les ingrédients secs et remuer pour enrober tous les grains.","Répartir dans les caissettes et presser légèrement avec le dos d’une cuillère.","Réfrigérer au moins 2 heures jusqu’à fermeté. Garder au frais, car les bouchées ramollissent dans une pièce chaude."],"photo":{"file":"File:Chocolate crackles.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Chocolate_crackles.jpg/500px-Chocolate_crackles.jpg","page":"https://commons.wikimedia.org/wiki/File:Chocolate_crackles.jpg","author":"Finbar.concaig","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"australian-rissoles-au","country":"AU","original":"Australian rissoles","title":"Rissoles australiennes au bœuf","en":"Australian beef rissoles","es":"Rissoles australianas de ternera","desc":"Galettes australiennes de viande hachée et légumes, cuites à la poêle; elles ne sont pas enveloppées de pâte.","cat":"Plat principal","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Rissoles","auth":"adapted","ing":[["Bœuf haché",500,"g",null],["Oignon",1,null,null],["Carotte",1,null,null],["Chapelure",60,"g",null],["Œuf",1,null,null],["Sauce Worcestershire",1,"c. à soupe",null],["Huile",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Râper finement carotte et oignon; presser l’excès d’eau de l’oignon.","Mélanger les légumes avec viande, chapelure, œuf, sauce Worcestershire, sel et poivre, sans trop travailler.","Former 8 galettes épaisses de 3/4 pouce et les réfrigérer 15 minutes pour les raffermir.","Cuire dans l’huile à feu moyen 5 à 6 minutes par face, jusqu’à coloration et température de 71 °C au centre.","Laisser reposer 3 minutes. Servir avec purée, légumes ou salade."],"photo":{"file":"File:Meat rissoles. Easy as 1-2-3 (2179666929).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Meat_rissoles._Easy_as_1-2-3_%282179666929%29.jpg/500px-Meat_rissoles._Easy_as_1-2-3_%282179666929%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Meat_rissoles._Easy_as_1-2-3_(2179666929).jpg","author":"Tanya Dropbear from Adelaide, Australia","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"lolly-cake-nz","country":"NZ","original":"Lolly cake","title":"Lolly cake (rouleau néo-zélandais aux bonbons)","en":"Lolly cake (New Zealand candy biscuit roll)","es":"Lolly cake (rollo neozelandés de galletas y dulces)","desc":"Dessert néo-zélandais sans cuisson de biscuits maltés et bonbons mousseux, enrobé de noix de coco.","cat":"Dessert","diff":"easy","prep":20,"cook":5,"serv":12,"reference":"https://en.wikipedia.org/wiki/Lolly_cake","auth":"adapted","ing":[["Biscuits maltés",250,"g",null],["Bonbons mousseux colorés",150,"g",null],["Beurre",100,"g",null],["Lait concentré sucré",180,"g",null],["Noix de coco râpée",60,"g",null]],"steps":["Écraser les biscuits en miettes fines, en laissant quelques petits morceaux. Couper les bonbons mousseux en dés.","Faire fondre le beurre doucement puis le mélanger au lait concentré.","Verser sur les biscuits et remuer. Ajouter les bonbons quand la préparation est tiède, pour ne pas les faire fondre.","Former un rouleau de 2 pouces de diamètre sur du papier cuisson et l’enrober de noix de coco.","Emballer et réfrigérer au moins 4 heures. Couper en 12 rondelles avec un couteau légèrement réchauffé."],"photo":{"file":"File:Lolly cake (2792116118).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Lolly_cake_%282792116118%29.jpg/500px-Lolly_cake_%282792116118%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Lolly_cake_(2792116118).jpg","author":"brent simpson from Auckland, New Zealand/Aotearoa","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"louise-cake-nz","country":"NZ","original":"Louise cake","title":"Louise cake (carrés néo-zélandais confiture et coco)","en":"Louise cake (New Zealand jam and coconut squares)","es":"Louise cake (cuadrados neozelandeses de mermelada y coco)","desc":"Dessert néo-zélandais à base sablée, confiture de framboise et meringue à la noix de coco.","cat":"Dessert","diff":"medium","prep":30,"cook":30,"serv":12,"reference":"https://en.wikipedia.org/wiki/Louise_cake","auth":"adapted","ing":[["Farine",180,"g",null],["Beurre",100,"g",null],["Sucre",60,"g",null],["Jaunes d’œufs",2,null,null],["Poudre à pâte",0.5,"c. à thé",null],["Confiture de framboise",150,"g",null],["Blancs d’œufs",2,null,null],["Sucre pour meringue",100,"g",null],["Noix de coco râpée",100,"g",null]],"steps":["Battre beurre et sucre, incorporer les jaunes puis farine et poudre à pâte pour obtenir une pâte souple.","Presser dans un moule chemisé de 8 pouces et cuire à 170 °C 12 minutes.","Étaler la confiture sur la base encore tiède, sans la mélanger à la pâte.","Monter les blancs en neige, ajouter progressivement le sucre de meringue puis incorporer la noix de coco.","Étaler sur la confiture et cuire encore 18 à 22 minutes, jusqu’à meringue légèrement dorée. Refroidir complètement avant de couper."],"photo":{"file":"File:Louise Slice.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Louise_Slice.jpg/500px-Louise_Slice.jpg","page":"https://commons.wikimedia.org/wiki/File:Louise_Slice.jpg","author":"Finbar.concaig","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ginger-crunch-nz","country":"NZ","original":"Ginger crunch","title":"Ginger crunch (carrés néo-zélandais au gingembre)","en":"Ginger crunch (New Zealand ginger squares)","es":"Ginger crunch (cuadrados neozelandeses de jengibre)","desc":"Carrés néo-zélandais à base croustillante et glaçage fondant au gingembre; adaptation domestique du classique.","cat":"Dessert","diff":"easy","prep":20,"cook":25,"serv":12,"reference":"https://www.chelsea.co.nz/recipes/browse-recipes/ginger-crunch","auth":"adapted","ing":[["Farine",230,"g",null],["Beurre pour base",150,"g",null],["Sucre",100,"g",null],["Gingembre pour base",1,"c. à thé",null],["Poudre à pâte",1,"c. à thé",null],["Beurre pour glaçage",80,"g",null],["Sucre glace",140,"g",null],["Sirop doré",2,"c. à soupe",null],["Gingembre pour glaçage",2,"c. à thé",null]],"steps":["Battre le beurre de la base avec le sucre. Ajouter farine, poudre à pâte et gingembre pour obtenir un mélange sableux.","Tasser fermement dans un moule chemisé de 8 pouces, en égalisant les coins.","Cuire à 180 °C 20 à 25 minutes, jusqu’à base bien dorée.","Chauffer doucement les ingrédients du glaçage en remuant jusqu’à mélange lisse, puis verser sur la base chaude.","Laisser prendre environ 1 heure. Découper en 12 carrés lorsque le glaçage est ferme mais encore facile à couper."],"photo":{"file":"File:Ginger crunch Edmonds Cookery Book 1998.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Ginger_crunch_Edmonds_Cookery_Book_1998.jpg/500px-Ginger_crunch_Edmonds_Cookery_Book_1998.jpg","page":"https://commons.wikimedia.org/wiki/File:Ginger_crunch_Edmonds_Cookery_Book_1998.jpg","author":"DrThneed","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"flapper-pie-ca","country":"CA","original":"Flapper pie","title":"Flapper pie (tarte des Prairies à la crème et meringue)","en":"Flapper pie (Canadian Prairie custard pie)","es":"Flapper pie (tarta canadiense de crema y merengue)","desc":"Tarte des Prairies canadiennes à croûte de biscuits, crème vanillée et meringue; association particulièrement forte avec l’Ouest canadien.","cat":"Dessert","diff":"medium","prep":30,"cook":15,"serv":8,"reference":"https://albertamilk.com/recipes/flapper-pie-an-old-prairie-favourite/","auth":"adapted","ing":[["Biscuits Graham émiettés",180,"g",null],["Beurre",80,"g",null],["Sucre pour croûte",30,"g",null],["Cannelle",0.5,"c. à thé",null],["Lait",500,"ml",null],["Sucre pour crème",100,"g",null],["Fécule de maïs",35,"g",null],["Jaunes d’œufs",3,null,null],["Vanille",1,"c. à thé",null],["Blancs d’œufs",3,null,null],["Sucre pour meringue",75,"g",null]],"steps":["Mélanger biscuits, beurre fondu, sucre de croûte et cannelle. Presser dans un moule de 9 pouces et cuire 8 minutes à 180 °C.","Fouetter jaunes, sucre de crème et fécule avec un peu de lait; ajouter le reste du lait et chauffer en remuant jusqu’à ébullition.","Cuire 1 minute après épaississement, ajouter la vanille et verser la crème chaude dans la croûte.","Monter les blancs en neige, ajouter progressivement le sucre de meringue et battre jusqu’à pics fermes.","Étaler la meringue sur la crème chaude en la reliant à la croûte. Dorer à 180 °C 8 à 12 minutes puis refroidir et réfrigérer 3 heures avant de servir."],"place":"ca-alberta","photo":{"file":"File:Blackfoot Truckstop Diner - Flapper Pie (16050866996).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Blackfoot_Truckstop_Diner_-_Flapper_Pie_%2816050866996%29.jpg/500px-Blackfoot_Truckstop_Diner_-_Flapper_Pie_%2816050866996%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Blackfoot_Truckstop_Diner_-_Flapper_Pie_(16050866996).jpg","author":"Elsie Hui","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"raisin-pie-ca","country":"CA","original":"Raisin pie","title":"Tarte canadienne aux raisins secs","en":"Canadian raisin pie","es":"Tarta canadiense de pasas","desc":"Tarte familiale canadienne à garniture de raisins secs épaissie, sous une deuxième croûte.","cat":"Dessert","diff":"medium","prep":25,"cook":45,"serv":8,"reference":"https://myislandbistrokitchen.com/2022/02/04/old-fashioned-raisin-pie-recipe/","auth":"adapted","ing":[["Pâte à tarte",500,"g",null],["Raisins secs",300,"g",null],["Eau",400,"ml",null],["Cassonade",100,"g",null],["Fécule de maïs",25,"g",null],["Jus de citron",2,"c. à soupe",null],["Beurre",20,"g",null],["Cannelle",0.5,"c. à thé",null],["Œuf",1,null,null]],"steps":["Mijoter raisins, 350 ml d’eau, cassonade et cannelle 10 minutes.","Délayer la fécule dans les 50 ml d’eau restants, verser dans les raisins et cuire 1 minute en remuant. Ajouter citron et beurre; laisser tiédir.","Foncer un moule de 9 pouces avec la moitié de la pâte. Ajouter la garniture puis couvrir avec la seconde abaisse.","Souder les bords, pratiquer plusieurs ouvertures et badigeonner d’œuf battu.","Cuire à 190 °C 40 à 45 minutes jusqu’à croûte dorée et garniture bouillonnante. Refroidir au moins 2 heures avant de couper."],"photo":{"file":"File:Raisin pie with lattice crust.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Raisin_pie_with_lattice_crust.JPG/500px-Raisin_pie_with_lattice_crust.JPG","page":"https://commons.wikimedia.org/wiki/File:Raisin_pie_with_lattice_crust.JPG","author":"Connormah","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"ployes-ca","country":"CA","original":"Ployes","title":"Ployes (galettes acadiennes au sarrasin)","en":"Ployes (Acadian buckwheat pancakes)","es":"Ployes (tortitas acadias de trigo sarraceno)","desc":"Galettes acadiennes de sarrasin, sans œufs ni lait, cuites traditionnellement sur une seule face.","cat":"Pain","diff":"easy","prep":15,"cook":20,"serv":12,"reference":"https://en.wikipedia.org/wiki/Ploye","auth":"adapted","ing":[["Farine de sarrasin",150,"g",null],["Farine de blé",100,"g",null],["Eau froide",250,"ml",null],["Eau bouillante",250,"ml",null],["Poudre à pâte",2,"c. à thé",null],["Sel",0.5,"c. à thé",null]],"steps":["Mélanger les deux farines avec sel et poudre à pâte. Incorporer l’eau froide pour obtenir une pâte lisse.","Verser l’eau bouillante progressivement en fouettant, puis laisser reposer 5 minutes.","Chauffer une poêle antiadhésive à feu moyen. Verser une petite louche de pâte et l’étaler en cercle mince.","Cuire sans retourner, environ 2 minutes, jusqu’à dessus entièrement pris et criblé de petits trous.","Empiler les galettes sous un linge propre. Servir chaudes, par exemple avec beurre ou accompagnement salé."],"photo":{"file":"File:Ployes with peaches.png","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Ployes_with_peaches.png/500px-Ployes_with_peaches.png","page":"https://commons.wikimedia.org/wiki/File:Ployes_with_peaches.png","author":"Cnrowley","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"peach-cobbler-us","country":"US","original":"Peach cobbler","title":"Peach cobbler (pêches sous pâte biscuitée)","en":"Peach cobbler (American peach dessert)","es":"Peach cobbler (postre estadounidense de melocotón)","desc":"Dessert américain de pêches juteuses sous une pâte biscuitée; adaptation en plat familial.","cat":"Dessert","diff":"easy","prep":25,"cook":40,"serv":6,"reference":"https://en.wikipedia.org/wiki/Peach_cobbler","auth":"adapted","ing":[["Pêches dénoyautées",800,"g",null],["Sucre pour fruits",80,"g",null],["Jus de citron",1,"c. à soupe",null],["Fécule de maïs",15,"g",null],["Farine",180,"g",null],["Sucre pour pâte",40,"g",null],["Poudre à pâte",2,"c. à thé",null],["Beurre froid",70,"g",null],["Lait",120,"ml",null],["Sel",0.25,"c. à thé",null]],"steps":["Couper les pêches en quartiers et les mélanger avec sucre des fruits, citron et fécule. Étaler dans un plat beurré de 8 pouces.","Mélanger farine, sucre de pâte, poudre à pâte et sel. Sabler avec le beurre froid.","Ajouter le lait et remuer juste assez pour former une pâte souple, sans la pétrir.","Déposer des cuillerées de pâte sur les fruits en laissant quelques espaces.","Cuire à 190 °C 35 à 40 minutes jusqu’à dessus doré et jus des fruits bouillonnant. Laisser reposer 15 minutes avant de servir."],"photo":{"file":"File:MP - peach cobbler 10.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/MP_-_peach_cobbler_10.jpg/500px-MP_-_peach_cobbler_10.jpg","page":"https://commons.wikimedia.org/wiki/File:MP_-_peach_cobbler_10.jpg","author":"Mark Pellegrini","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"boston-cream-pie-us","country":"US","original":"Boston cream pie","title":"Boston cream pie (gâteau vanille, crème et chocolat)","en":"Boston cream pie (custard and chocolate cake)","es":"Boston cream pie (pastel de crema y chocolate)","desc":"Gâteau américain à deux couches de génoise, crème pâtissière et glaçage au chocolat, malgré son nom de pie.","cat":"Dessert","diff":"medium","prep":45,"cook":30,"serv":10,"reference":"https://en.wikipedia.org/wiki/Boston_cream_pie","auth":"adapted","ing":[["Farine",180,"g",null],["Sucre pour gâteau",160,"g",null],["Œufs",3,null,null],["Beurre pour gâteau",70,"g",null],["Lait pour gâteau",100,"ml",null],["Poudre à pâte",1.5,"c. à thé",null],["Lait pour crème",400,"ml",null],["Sucre pour crème",70,"g",null],["Jaunes d’œufs",3,null,null],["Fécule de maïs",30,"g",null],["Vanille",2,"c. à thé",null],["Chocolat noir",150,"g",null],["Crème 35 %",120,"ml",null]],"steps":["Battre les œufs et le sucre du gâteau 5 minutes. Incorporer farine et poudre à pâte, puis lait et beurre fondus tiédis.","Verser dans un moule de 8 pouces et cuire à 180 °C 25 à 30 minutes, jusqu’à cure-dent propre. Refroidir et couper horizontalement.","Pour la crème, fouetter jaunes, sucre et fécule avec un peu du lait; ajouter le reste et cuire en remuant jusqu’à ébullition, puis 1 minute. Ajouter la moitié de la vanille; filmer au contact et refroidir.","Garnir la moitié inférieure du gâteau de crème froide, puis poser la seconde moitié.","Verser la crème chaude sur le chocolat haché, ajouter le reste de vanille et remuer. Napper le dessus; réfrigérer 2 heures avant de servir."],"photo":{"file":"File:Bostoncreampie.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/85/Bostoncreampie.jpg","page":"https://commons.wikimedia.org/wiki/File:Bostoncreampie.jpg","author":"cara fealy choate","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"whoopie-pies-us","country":"US","original":"Whoopie pies","title":"Whoopie pies (biscuits moelleux au chocolat et crème)","en":"Whoopie pies (chocolate cream sandwiches)","es":"Whoopie pies (pastelitos de chocolate y crema)","desc":"Petits gâteaux américains au chocolat, assemblés deux par deux autour d’une crème au beurre.","cat":"Dessert","diff":"medium","prep":30,"cook":12,"serv":12,"reference":"https://en.wikipedia.org/wiki/Whoopie_pie","auth":"adapted","ing":[["Farine",220,"g",null],["Cacao",50,"g",null],["Beurre pour pâte",100,"g",null],["Cassonade",150,"g",null],["Œuf",1,null,null],["Babeurre",180,"ml",null],["Bicarbonate",1,"c. à thé",null],["Sel",0.25,"c. à thé",null],["Beurre pour crème",100,"g",null],["Sucre glace",180,"g",null],["Vanille",1,"c. à thé",null],["Lait pour crème",1,"c. à soupe",null]],"steps":["Battre beurre de pâte et cassonade, puis ajouter l’œuf. Mélanger séparément farine, cacao, bicarbonate et sel.","Incorporer les ingrédients secs en alternance avec le babeurre, sans battre longuement.","Déposer 24 petits tas réguliers sur deux plaques chemisées. Cuire à 180 °C 10 à 12 minutes jusqu’à centres pris.","Refroidir complètement. Fouetter beurre de crème, sucre glace, vanille et lait jusqu’à crème légère.","Assembler les gâteaux deux par deux avec la garniture. Réfrigérer si non servis immédiatement et laisser tempérer 10 minutes avant de manger."],"photo":{"file":"File:Whoopie pie with dusting of confectioner's sugar.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/43/Whoopie_pie_with_dusting_of_confectioner%27s_sugar.jpg","page":"https://commons.wikimedia.org/wiki/File:Whoopie_pie_with_dusting_of_confectioner%27s_sugar.jpg","author":"Arnold Gatilao","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"pecan-pie-us","country":"US","original":"Pecan pie","title":"Pecan pie (tarte américaine aux pacanes)","en":"Pecan pie (American pecan tart)","es":"Pecan pie (tarta estadounidense de nueces pecanas)","desc":"Tarte américaine aux pacanes dans une garniture aux œufs et sirop.","cat":"Dessert","diff":"easy","prep":20,"cook":55,"serv":8,"reference":"https://en.wikipedia.org/wiki/Pecan_pie","auth":"adapted","ing":[["Pâte à tarte",300,"g",null],["Pacanes",200,"g",null],["Œufs",3,null,null],["Sirop de maïs",200,"ml",null],["Cassonade",100,"g",null],["Beurre",50,"g",null],["Vanille",1,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Foncer un moule de 9 pouces avec la pâte et réfrigérer pendant la préparation de la garniture.","Fouetter œufs, sirop, cassonade, beurre fondu tiédi, vanille et sel.","Disposer les pacanes dans le fond puis verser doucement la garniture pour les répartir.","Cuire à 175 °C 50 à 55 minutes, jusqu’à bords pris et centre encore légèrement tremblant; protéger la croûte si elle colore trop.","Refroidir complètement sur une grille avant de couper. Réfrigérer les restes."],"photo":{"file":"File:Pecan pie, November 2010.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/be/Pecan_pie%2C_November_2010.jpg","page":"https://commons.wikimedia.org/wiki/File:Pecan_pie,_November_2010.jpg","author":"Joe Hakim","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"shoofly-pie-us","country":"US","original":"Shoofly pie","title":"Shoofly pie (tarte de Pennsylvanie à la mélasse)","en":"Shoofly pie (Pennsylvania molasses crumb pie)","es":"Shoofly pie (tarta de melaza de Pensilvania)","desc":"Tarte américaine de tradition Pennsylvania Dutch, à la mélasse et garniture de miettes.","cat":"Dessert","diff":"medium","prep":25,"cook":45,"serv":8,"reference":"https://en.wikipedia.org/wiki/Shoofly_pie","auth":"adapted","ing":[["Pâte à tarte",300,"g",null],["Farine",180,"g",null],["Cassonade",100,"g",null],["Beurre froid",70,"g",null],["Mélasse",200,"ml",null],["Eau chaude",180,"ml",null],["Bicarbonate",0.5,"c. à thé",null],["Œuf",1,null,null]],"steps":["Foncer un moule de 9 pouces et mettre au frais. Sabler farine, cassonade et beurre pour obtenir des miettes.","Mélanger mélasse et eau chaude. Ajouter le bicarbonate, laisser tiédir puis incorporer l’œuf battu.","Répartir la moitié des miettes dans le fond de tarte et verser le liquide à la mélasse.","Parsemer le reste des miettes sans les tasser.","Cuire 15 minutes à 190 °C puis 25 à 30 minutes à 175 °C, jusqu’à garniture prise. Refroidir avant de découper."],"photo":{"file":"File:Shoofly pie.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/56/Shoofly_pie.jpg","page":"https://commons.wikimedia.org/wiki/File:Shoofly_pie.jpg","author":"Christine","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"snickerdoodles-us","country":"US","original":"Snickerdoodles","title":"Snickerdoodles (biscuits américains à la cannelle)","en":"Snickerdoodles (American cinnamon cookies)","es":"Snickerdoodles (galletas estadounidenses de canela)","desc":"Biscuits américains moelleux enrobés de sucre et cannelle, avec une légère note acidulée de crème de tartre.","cat":"Dessert","diff":"easy","prep":20,"cook":12,"serv":24,"reference":"https://en.wikipedia.org/wiki/Snickerdoodle","auth":"adapted","ing":[["Farine",280,"g",null],["Beurre",150,"g",null],["Sucre",170,"g",null],["Œuf",1,null,null],["Crème de tartre",1,"c. à thé",null],["Bicarbonate",0.5,"c. à thé",null],["Sel",0.25,"c. à thé",null],["Sucre pour enrober",50,"g",null],["Cannelle",2,"c. à thé",null]],"steps":["Battre beurre et sucre jusqu’à texture crémeuse, puis incorporer l’œuf.","Mélanger farine, crème de tartre, bicarbonate et sel; incorporer sans pétrir longuement.","Mélanger le sucre d’enrobage et la cannelle. Former 24 boules de pâte et les rouler dans ce mélange.","Disposer sur deux plaques en les espaçant. Cuire à 180 °C 10 à 12 minutes, jusqu’à bords pris et centres encore souples.","Laisser reposer 5 minutes sur la plaque avant de transférer sur une grille."],"photo":{"file":"File:Snickerdoodles close-up.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Snickerdoodles_close-up.jpg/500px-Snickerdoodles_close-up.jpg","page":"https://commons.wikimedia.org/wiki/File:Snickerdoodles_close-up.jpg","author":"Ginny from USA","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"chicken-and-dumplings-us","country":"US","original":"Chicken and dumplings","title":"Chicken and dumplings (poulet américain aux boulettes)","en":"Chicken and dumplings (American chicken stew)","es":"Chicken and dumplings (guiso estadounidense de pollo)","desc":"Mijoté américain de poulet et légumes, avec boulettes de pâte cuites à la vapeur dans le bouillon.","cat":"Plat principal","diff":"medium","prep":25,"cook":45,"serv":4,"reference":"https://en.wikipedia.org/wiki/Chicken_and_dumplings","auth":"adapted","ing":[["Poulet désossé",600,"g",null],["Oignon",1,null,null],["Carottes",2,null,null],["Céleri",2,"branches",null],["Bouillon de poulet",1000,"ml",null],["Beurre",30,"g",null],["Farine pour sauce",25,"g",null],["Farine pour boulettes",180,"g",null],["Poudre à pâte",2,"c. à thé",null],["Lait",130,"ml",null],["Beurre pour boulettes",25,"g",null],["Thym",0.5,"c. à thé",null],["Sel",0.75,"c. à thé",null]],"steps":["Faire revenir oignon, carottes et céleri hachés dans le beurre 5 minutes. Ajouter farine de sauce et remuer 1 minute.","Verser le bouillon graduellement, ajouter poulet en morceaux et thym, puis mijoter 20 minutes.","Mélanger farine des boulettes, poudre à pâte et sel. Ajouter beurre fondu et lait pour former une pâte souple.","Déposer 8 cuillerées de pâte dans le bouillon frémissant. Couvrir et cuire 15 minutes sans ouvrir fréquemment.","Vérifier poulet à 74 °C et intérieur d’une boulette sans pâte crue. Servir aussitôt avec le jus et les légumes."],"photo":{"file":"File:Chicken and dumplings.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Chicken_and_dumplings.JPG/500px-Chicken_and_dumplings.JPG","page":"https://commons.wikimedia.org/wiki/File:Chicken_and_dumplings.JPG","author":"Amadscientist","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"fried-green-tomatoes-us","country":"US","original":"Fried green tomatoes","title":"Tomates vertes frites à l’américaine","en":"Fried green tomatoes (American cornmeal-coated tomatoes)","es":"Tomates verdes fritos al estilo estadounidense","desc":"Tranches de tomates encore vertes, panées à la semoule de maïs puis frites; elles doivent être fermes.","cat":"Entrée","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Fried_green_tomatoes","auth":"adapted","ing":[["Tomates vertes fermes",4,null,null],["Farine",60,"g",null],["Semoule de maïs fine",100,"g",null],["Chapelure",50,"g",null],["Œuf",1,null,null],["Babeurre",100,"ml",null],["Huile de friture",500,"ml",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Couper les tomates en tranches de 1/4 pouce. Saler légèrement et laisser reposer 10 minutes, puis éponger.","Préparer farine, œuf battu avec babeurre, et mélange semoule-chapelure-poivre dans trois assiettes.","Passer chaque tranche dans farine, mélange liquide puis panure, en pressant doucement.","Frire dans l’huile à 170 °C environ 2 minutes par face, jusqu’à croûte dorée et tomate attendrie.","Égoutter sur une grille et servir chaud; ne pas empiler pour garder la panure croustillante."],"photo":{"file":"File:Fried green tomatoes.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Fried_green_tomatoes.jpg","page":"https://commons.wikimedia.org/wiki/File:Fried_green_tomatoes.jpg","author":"ninjapoodles","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"corn-pudding-us","country":"US","original":"Corn pudding","title":"Corn pudding (gratin américain de maïs)","en":"Corn pudding (American baked corn custard)","es":"Corn pudding (budín estadounidense de maíz)","desc":"Gratin moelleux américain de maïs lié avec lait, œufs et un peu de farine; version salée légèrement douce.","cat":"Accompagnement","diff":"easy","prep":15,"cook":45,"serv":6,"reference":"https://en.wikipedia.org/wiki/Corn_pudding","auth":"adapted","ing":[["Grains de maïs",500,"g",null],["Lait",250,"ml",null],["Crème 35 %",100,"ml",null],["Œufs",3,null,null],["Farine",35,"g",null],["Beurre",40,"g",null],["Sucre",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Mixer la moitié du maïs avec le lait pour donner une texture crémeuse, puis garder le reste entier.","Fouetter œufs, crème, farine, beurre fondu, sucre, sel et poivre.","Réunir les préparations et verser dans un plat beurré de 8 pouces.","Cuire à 180 °C 40 à 45 minutes, jusqu’à bords dorés et centre pris, sans le dessécher.","Laisser reposer 10 minutes avant de servir en accompagnement."],"photo":{"file":"File:Trader Joe's Corn Pudding Done (16237574939).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Trader_Joe%27s_Corn_Pudding_Done_%2816237574939%29.jpg/500px-Trader_Joe%27s_Corn_Pudding_Done_%2816237574939%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Trader_Joe%27s_Corn_Pudding_Done_(16237574939).jpg","author":"Willis Lam","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"cheese-grits-us","country":"US","original":"Cheese grits","title":"Cheese grits (semoule de maïs américaine au fromage)","en":"Cheese grits (American creamy corn grits)","es":"Cheese grits (sémola de maíz estadounidense con queso)","desc":"Semoule de maïs du sud des États-Unis cuite crémeuse puis enrichie de cheddar. La photo montre les grits garnis de bacon et d’œuf; ces accompagnements ne font pas partie de la préparation décrite.","cat":"Accompagnement","diff":"easy","prep":10,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Grits","auth":"adapted","ing":[["Grits de maïs",180,"g","cuisson traditionnelle, pas instantanés"],["Eau",600,"ml",null],["Lait",400,"ml",null],["Cheddar",120,"g",null],["Beurre",30,"g",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Porter eau et lait au frémissement dans une casserole épaisse; ajouter le sel.","Verser les grits en pluie en fouettant pour éviter les grumeaux.","Cuire à feu doux 25 à 30 minutes en remuant souvent, jusqu’à grains tendres; suivre le temps du produit si différent.","Ajouter beurre puis cheddar râpé hors du feu. Détendre avec un peu d’eau chaude si nécessaire.","Poivrer et servir immédiatement; la préparation épaissit en refroidissant."],"photo":{"file":"File:Grits with cheese, bacon, green onion and poached egg.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/49/Grits_with_cheese%2C_bacon%2C_green_onion_and_poached_egg.jpg","page":"https://commons.wikimedia.org/wiki/File:Grits_with_cheese,_bacon,_green_onion_and_poached_egg.jpg","author":"Farther Along","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"syllabub-gb","country":"GB","original":"Syllabub","title":"Syllabub (crème anglaise au citron et vin)","en":"Syllabub (English lemon and wine cream)","es":"Syllabub (crema inglesa de limón y vino)","desc":"Dessert anglais mousseux de crème, sucre, citron et vin blanc; version moderne servie en verres.","cat":"Dessert","diff":"easy","prep":15,"cook":0,"serv":4,"reference":"https://en.wikipedia.org/wiki/Syllabub","auth":"adapted","ing":[["Crème 35 %",250,"ml",null],["Vin blanc",60,"ml",null],["Sucre",50,"g",null],["Jus de citron",1,"c. à soupe",null],["Zeste de citron",1,"c. à thé",null]],"steps":["Mélanger vin, sucre, jus et zeste de citron jusqu’à dissolution du sucre.","Refroidir le mélange et la crème au réfrigérateur 20 minutes.","Fouetter la crème jusqu’à pics souples, sans la transformer en beurre.","Incorporer le mélange au vin progressivement en fouettant brièvement, puis répartir dans quatre verres.","Réfrigérer 1 heure et servir le jour même. Le vin reste alcoolisé puisque le dessert ne cuit pas."],"photo":{"file":"File:Syllabub.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a1/Syllabub.jpg","page":"https://commons.wikimedia.org/wiki/File:Syllabub.jpg","author":"Man vyi","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"treacle-tart-gb","country":"GB","original":"Treacle tart","title":"Treacle tart (tarte anglaise au sirop doré)","en":"Treacle tart (English golden syrup tart)","es":"Treacle tart (tarta inglesa de jarabe dorado)","desc":"Tarte anglaise au golden syrup, mie de pain et citron; malgré le nom, la version classique utilise le sirop doré.","cat":"Dessert","diff":"easy","prep":25,"cook":35,"serv":8,"reference":"https://en.wikipedia.org/wiki/Treacle_tart","auth":"adapted","ing":[["Pâte à tarte",300,"g",null],["Golden syrup",300,"g",null],["Mie de pain fraîche émiettée",140,"g",null],["Jus de citron",2,"c. à soupe",null],["Zeste de citron",1,"c. à thé",null],["Œuf",1,null,null]],"steps":["Foncer un moule de 9 pouces, réfrigérer 20 minutes puis précuire à 180 °C 10 minutes avec des poids.","Tiédir le sirop doré pour l’assouplir, puis incorporer mie de pain, citron et zeste.","Laisser tiédir davantage et incorporer l’œuf battu pour obtenir une garniture homogène.","Verser dans la croûte précuite et cuire à 180 °C 25 à 30 minutes, jusqu’à garniture prise et bords dorés.","Laisser refroidir au moins 30 minutes avant de servir; la garniture continue à se raffermir."],"photo":{"file":"File:Treacle Tart with clotted cream.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6e/Treacle_Tart_with_clotted_cream.jpg","page":"https://commons.wikimedia.org/wiki/File:Treacle_Tart_with_clotted_cream.jpg","author":"John Bracken","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"bread-and-butter-pudding-gb","country":"GB","original":"Bread and butter pudding","title":"Bread and butter pudding (pouding anglais au pain)","en":"Bread and butter pudding (English baked bread custard)","es":"Bread and butter pudding (pudin inglés de pan y mantequilla)","desc":"Dessert anglais de tranches de pain beurrées, raisins et crème aux œufs cuite au four.","cat":"Dessert","diff":"easy","prep":20,"cook":40,"serv":6,"reference":"https://en.wikipedia.org/wiki/Bread_and_butter_pudding","auth":"adapted","ing":[["Pain blanc rassis",300,"g",null],["Beurre",50,"g",null],["Raisins secs",80,"g",null],["Lait",400,"ml",null],["Crème 35 %",150,"ml",null],["Œufs",3,null,null],["Sucre",80,"g",null],["Vanille",1,"c. à thé",null],["Muscade",0.25,"c. à thé",null]],"steps":["Beurrer les tranches de pain et les couper en triangles. Les disposer dans un plat beurré de 8 pouces avec les raisins.","Fouetter œufs, sucre, lait, crème, vanille et muscade sans faire beaucoup de mousse.","Verser sur le pain en humectant toutes les surfaces et laisser imbiber 20 minutes.","Cuire à 170 °C 35 à 40 minutes, jusqu’à centre pris et dessus doré.","Laisser tiédir 10 minutes. Servir à la cuillère et réfrigérer les restes."],"photo":{"file":"File:Bread and Butter Pudding and Custard.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Bread_and_Butter_Pudding_and_Custard.jpg/500px-Bread_and_Butter_Pudding_and_Custard.jpg","page":"https://commons.wikimedia.org/wiki/File:Bread_and_Butter_Pudding_and_Custard.jpg","author":"Nick Richards from London, UK","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"spotted-dick-gb","country":"GB","original":"Spotted dick","title":"Spotted dick (pouding anglais vapeur aux raisins)","en":"Spotted dick (English steamed raisin pudding)","es":"Spotted dick (pudin inglés de pasas al vapor)","desc":"Pouding anglais vapeur aux raisins; adaptation au beurre froid plutôt qu’au suif traditionnel.","cat":"Dessert","diff":"medium","prep":25,"cook":90,"serv":6,"reference":"https://en.wikipedia.org/wiki/Spotted_dick","auth":"adapted","ing":[["Farine",250,"g",null],["Beurre froid",100,"g",null],["Sucre",70,"g",null],["Raisins secs",150,"g",null],["Lait",180,"ml",null],["Poudre à pâte",2,"c. à thé",null],["Zeste de citron",1,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Mélanger farine, poudre à pâte, sucre, zeste et sel. Râper le beurre froid et l’enrober de farine.","Ajouter raisins et lait, puis remuer juste assez pour former une pâte épaisse.","Verser dans un bol résistant à la chaleur beurré de 1,2 litre. Couvrir de papier cuisson puis papier aluminium bien attaché, avec un pli pour laisser gonfler.","Placer sur une grille dans une grande casserole; verser de l’eau bouillante à mi-hauteur du bol. Couvrir et cuire à vapeur douce 90 minutes, en maintenant le niveau d’eau.","Vérifier la cuisson au centre, laisser reposer 5 minutes et démouler. Servir avec crème anglaise préparée séparément."],"photo":{"file":"File:Spotted Dick Wikimeet London 2005.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Spotted_Dick_Wikimeet_London_2005.jpg/500px-Spotted_Dick_Wikimeet_London_2005.jpg","page":"https://commons.wikimedia.org/wiki/File:Spotted_Dick_Wikimeet_London_2005.jpg","author":"","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"welsh-cakes-gb","country":"GB","original":"Welsh cakes","title":"Welsh cakes (galettes galloises aux raisins)","en":"Welsh cakes (Welsh raisin griddle cakes)","es":"Welsh cakes (galletas galesas a la plancha)","desc":"Petites galettes du pays de Galles, légèrement sucrées, cuites sur une plaque ou une poêle.","cat":"Dessert","diff":"easy","prep":20,"cook":15,"serv":12,"reference":"https://www.visitwales.com/things-do/food-and-drink/welsh-food-and-recipes/traditional-welsh-cakes-recipe","auth":"adapted","ing":[["Farine",250,"g",null],["Beurre froid",100,"g",null],["Sucre",70,"g",null],["Raisins de Corinthe",70,"g",null],["Œuf",1,null,null],["Lait",2,"c. à soupe",null],["Poudre à pâte",1,"c. à thé",null],["Muscade",0.25,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Mélanger farine, poudre à pâte, muscade et sel. Sabler avec le beurre, puis ajouter sucre et raisins.","Incorporer l’œuf et assez de lait pour obtenir une pâte ferme mais malléable.","Abaisser à 1/4 pouce sur un plan fariné et découper 12 disques.","Cuire dans une poêle légèrement beurrée à feu moyen doux 3 à 4 minutes par face, jusqu’à dorure et centre cuit.","Laisser tiédir; servir nature ou avec un peu de sucre saupoudré."],"place":"gb-wales","photo":{"file":"File:Welsh cakes2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Welsh_cakes2.jpg/500px-Welsh_cakes2.jpg","page":"https://commons.wikimedia.org/wiki/File:Welsh_cakes2.jpg","author":"Moochocoogle at English Wikipedia","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"clapshot-gb","country":"GB","original":"Clapshot","title":"Clapshot (purée écossaise de pommes de terre et rutabaga)","en":"Clapshot (Scottish potato and swede mash)","es":"Clapshot (puré escocés de patata y colinabo)","desc":"Purée écossaise associée aux Orcades, combinant pommes de terre, rutabaga et ciboulette.","cat":"Accompagnement","diff":"easy","prep":20,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Clapshot","auth":"adapted","ing":[["Pommes de terre",600,"g",null],["Rutabaga",500,"g",null],["Beurre",50,"g",null],["Ciboulette",15,"g",null],["Sel",0.75,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Peler pommes de terre et rutabaga. Couper le rutabaga en cubes plus petits, car il cuit plus lentement.","Cuire le rutabaga dans l’eau salée 10 minutes, puis ajouter les pommes de terre.","Poursuivre 20 minutes, jusqu’à légumes facilement écrasables, puis égoutter soigneusement.","Remettre une minute dans la casserole chaude pour enlever l’excès d’eau; écraser avec le beurre.","Ajouter ciboulette et poivre, goûter et ajuster le sel. Servir chaud en accompagnement."],"place":"gb-scotland","photo":{"file":"File:Clapshot and oatcakes.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Clapshot_and_oatcakes.jpg/500px-Clapshot_and_oatcakes.jpg","page":"https://commons.wikimedia.org/wiki/File:Clapshot_and_oatcakes.jpg","author":"Mutt Lunker","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"rumbledethumps-gb","country":"GB","original":"Rumbledethumps","title":"Rumbledethumps (gratin écossais de pommes de terre et chou)","en":"Rumbledethumps (Scottish potato and cabbage bake)","es":"Rumbledethumps (gratinado escocés de patata y col)","desc":"Gratin écossais de pommes de terre écrasées, chou et oignon, couvert de cheddar.","cat":"Accompagnement","diff":"easy","prep":20,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Rumbledethumps","auth":"adapted","ing":[["Pommes de terre",700,"g",null],["Chou vert",350,"g",null],["Oignon",1,null,null],["Beurre",50,"g",null],["Cheddar",100,"g",null],["Sel",0.75,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Cuire les pommes de terre pelées en cubes dans l’eau salée 20 minutes, puis égoutter.","Pendant ce temps, attendrir l’oignon haché et le chou émincé dans la moitié du beurre 12 à 15 minutes.","Écraser les pommes de terre avec le beurre restant puis incorporer les légumes, sel et poivre.","Étaler dans un plat de 8 pouces et couvrir de cheddar râpé.","Cuire à 200 °C 15 à 20 minutes, jusqu’à dessus gratiné et préparation chaude à cœur."],"place":"gb-scotland","photo":{"file":"File:Rumbledethumps.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Rumbledethumps.JPG/500px-Rumbledethumps.JPG","page":"https://commons.wikimedia.org/wiki/File:Rumbledethumps.JPG","author":"Glane23","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"barmbrack-ie","country":"IE","original":"Barmbrack","title":"Barmbrack (pain irlandais aux fruits)","en":"Barmbrack (Irish fruit bread)","es":"Barmbrack (pan irlandés con frutas)","desc":"Pain irlandais levé aux fruits secs infusés dans le thé, souvent associé à Halloween. Prévoir 4 heures de trempage et environ 2 heures de levée en plus du temps actif.","cat":"Pain","diff":"easy","prep":30,"cook":35,"serv":10,"reference":"https://en.wikipedia.org/wiki/Barmbrack","auth":"adapted","ing":[["Farine",300,"g",null],["Raisins secs",150,"g",null],["Thé fort",180,"ml","pour le trempage"],["Lait tiède",120,"ml",null],["Œuf",1,null,null],["Beurre mou",40,"g",null],["Sucre",50,"g",null],["Levure boulangère instantanée",6,"g",null],["Cannelle",0.5,"c. à thé",null],["Sel",0.5,"c. à thé",null]],"steps":["Tremper les raisins dans le thé 4 heures, puis les égoutter et bien les éponger.","Mélanger farine, levure, sucre, cannelle et sel. Ajouter lait et œuf, puis pétrir 8 minutes. Incorporer le beurre et pétrir 5 minutes de plus.","Ajouter les fruits égouttés, couvrir et laisser doubler de volume environ 1 heure dans un endroit tiède.","Former un pain rond et le déposer dans un moule de 8 pouces chemisé. Couvrir et laisser lever 45 à 60 minutes.","Cuire à 180 °C environ 35 minutes, jusqu’à pain bien doré, centre cuit et dessous sonnant creux. Laisser refroidir sur une grille avant de couper."],"photo":{"file":"File:Commercial Barmbrack.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/78/Commercial_Barmbrack.jpg","page":"https://commons.wikimedia.org/wiki/File:Commercial_Barmbrack.jpg","author":"Solo Beckett","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"cougnou-be","country":"BE","original":"Cougnou","title":"Cougnou (brioche belge de Noël)","en":"Cougnou (Belgian Christmas bread)","es":"Cougnou (pan dulce belga de Navidad)","desc":"Brioche belge façonnée avec un corps central et deux extrémités rondes; adaptation aux raisins.","cat":"Pain","diff":"medium","prep":30,"cook":25,"serv":8,"reference":"https://en.wikipedia.org/wiki/Cougnou","auth":"adapted","ing":[["Farine",400,"g",null],["Lait",180,"ml",null],["Beurre",80,"g",null],["Sucre",60,"g",null],["Œuf",1,null,null],["Levure sèche",7,"g",null],["Raisins secs",100,"g",null],["Sel",0.5,"c. à thé",null],["Œuf pour dorure",1,null,null]],"steps":["Mélanger farine, levure, sucre et sel. Ajouter lait tiède et œuf, puis pétrir 8 minutes.","Incorporer le beurre ramolli en plusieurs fois et pétrir encore 5 minutes. Ajouter les raisins; couvrir et laisser lever 1 heure 30.","Former un gros ovale avec les deux tiers de la pâte et deux boules avec le reste. Les attacher aux extrémités en humectant les points de contact.","Laisser gonfler 45 minutes sur une plaque, puis badigeonner d’œuf battu.","Cuire à 180 °C 25 à 30 minutes, jusqu’à brioche dorée et centre cuit. Refroidir sur une grille."],"photo":{"file":"File:Queniole.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Queniole.jpg","page":"https://commons.wikimedia.org/wiki/File:Queniole.jpg","author":"No machine-readable author provided. Mica assumed (based on copyright claims).","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"Wikimedia Commons"}},{"slug":"boterkoek-nl","country":"NL","original":"Boterkoek","title":"Boterkoek (gâteau néerlandais au beurre)","en":"Boterkoek (Dutch butter cake)","es":"Boterkoek (pastel neerlandés de mantequilla)","desc":"Gâteau néerlandais dense au beurre, coupé en petites pointes ou carrés.","cat":"Dessert","diff":"easy","prep":15,"cook":25,"serv":12,"reference":"https://www.24kitchen.nl/recepten/klassieke-boterkoek","auth":"adapted","ing":[["Farine",250,"g",null],["Beurre",200,"g",null],["Sucre",160,"g",null],["Œuf",1,null,null],["Vanille",1,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Battre beurre ramolli et sucre jusqu’à texture crémeuse. Battre l’œuf séparément et en réserver une cuillère pour dorer.","Ajouter le reste de l’œuf, vanille et sel, puis incorporer la farine sans long pétrissage.","Tasser la pâte dans un moule beurré de 8 pouces et lisser avec une cuillère légèrement humide.","Badigeonner de l’œuf réservé, tracer un quadrillage à la fourchette et cuire à 180 °C 25 à 30 minutes.","Laisser refroidir complètement dans le moule avant de découper; le gâteau reste dense et tendre."],"photo":{"file":"File:Boterkoek.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Boterkoek.JPG/500px-Boterkoek.JPG","page":"https://commons.wikimedia.org/wiki/File:Boterkoek.JPG","author":"JZ85","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"ontbijtkoek-nl","country":"NL","original":"Ontbijtkoek","title":"Ontbijtkoek (pain d’épices néerlandais)","en":"Ontbijtkoek (Dutch spiced loaf)","es":"Ontbijtkoek (pan especiado neerlandés)","desc":"Pain-gâteau néerlandais aux épices et farine de seigle, souvent servi en tranches avec du beurre.","cat":"Pain","diff":"easy","prep":15,"cook":55,"serv":10,"reference":"https://en.wikipedia.org/wiki/Ontbijtkoek","auth":"adapted","ing":[["Farine de seigle",180,"g",null],["Farine de blé",120,"g",null],["Lait",220,"ml",null],["Miel",150,"g",null],["Cassonade",100,"g",null],["Poudre à pâte",2,"c. à thé",null],["Cannelle",2,"c. à thé",null],["Gingembre",0.5,"c. à thé",null],["Clou de girofle moulu",0.25,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Mélanger les farines, poudre à pâte, épices et sel. Chemiser un moule à pain de 9 pouces.","Tiédir lait, miel et cassonade juste assez pour dissoudre le sucre.","Verser dans les ingrédients secs et remuer jusqu’à pâte épaisse et homogène.","Cuire à 160 °C 50 à 60 minutes, jusqu’à cure-dent propre; protéger le dessus si nécessaire.","Refroidir complètement puis emballer. Attendre idéalement le lendemain pour des tranches régulières et une texture moelleuse."],"photo":{"file":"File:Slice of ontbijtkoek.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Slice_of_ontbijtkoek.jpg/500px-Slice_of_ontbijtkoek.jpg","page":"https://commons.wikimedia.org/wiki/File:Slice_of_ontbijtkoek.jpg","author":"Flanamsterdam","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"tompoes-nl","country":"NL","original":"Tompoes","title":"Tompoes (millefeuille néerlandais glacé)","en":"Tompoes (Dutch iced custard slice)","es":"Tompoes (milhojas neerlandés glaseado)","desc":"Pâtisserie néerlandaise à crème vanillée entre deux rectangles feuilletés, avec glaçage rose.","cat":"Dessert","diff":"medium","prep":40,"cook":25,"serv":8,"reference":"https://en.wikipedia.org/wiki/Tompoes","auth":"adapted","ing":[["Pâte feuilletée",400,"g",null],["Lait",500,"ml",null],["Jaunes d’œufs",4,null,null],["Sucre",90,"g",null],["Fécule de maïs",50,"g",null],["Vanille",1,"c. à thé",null],["Beurre",25,"g",null],["Sucre glace",150,"g",null],["Eau",2,"c. à soupe",null],["Colorant rose alimentaire",1,"goutte","facultatif"]],"steps":["Abaisser deux rectangles de pâte de 6 sur 10 pouces. Piquer et cuire à 200 °C 20 à 25 minutes sous une seconde plaque pour limiter le gonflement.","Fouetter jaunes, sucre et fécule avec un peu de lait. Ajouter le lait chaud progressivement, remettre au feu et cuire jusqu’à ébullition, puis 1 minute.","Ajouter beurre et vanille; couvrir au contact et refroidir rapidement.","Étaler la crème épaisse sur la première pâte. Mélanger sucre glace, eau et colorant; glacer la seconde pâte et la découper en 8 rectangles.","Poser les rectangles glacés sur la crème, réfrigérer 3 heures et découper la base en suivant leurs bords."],"photo":{"file":"File:Tompoes Belgie.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/6/64/Tompoes_Belgie.JPG","page":"https://commons.wikimedia.org/wiki/File:Tompoes_Belgie.JPG","author":"Kiekebanus at Dutch Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"papet-vaudois-ch","country":"CH","original":"Papet vaudois","title":"Papet vaudois (poireaux, pommes de terre et saucisse)","en":"Papet vaudois (Swiss leek and potato stew)","es":"Papet vaudois (guiso suizo de puerro y patata)","desc":"Plat vaudois de poireaux et pommes de terre, servi avec saucisse aux choux; adaptation avec saucisse fumée si le produit suisse est introuvable.","cat":"Plat principal","diff":"easy","prep":20,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Papet_vaudois","auth":"adapted","ing":[["Poireaux",800,"g",null],["Pommes de terre",600,"g",null],["Saucisses aux choux",600,"g","ou saucisse fumée adaptée"],["Beurre",30,"g",null],["Vin blanc",100,"ml",null],["Bouillon",250,"ml",null],["Crème",100,"ml",null],["Vinaigre blanc",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Laver soigneusement les poireaux et les couper en tronçons. Peler et couper les pommes de terre en cubes.","Attendrir les poireaux dans le beurre 5 minutes, puis verser vin et bouillon.","Ajouter pommes de terre et mijoter à couvert 25 à 30 minutes, jusqu’à tendreté.","Cuire les saucisses séparément à frémissement selon leur emballage; si elles contiennent de la viande crue, atteindre 74 °C au centre.","Écraser légèrement quelques pommes de terre pour lier les poireaux. Ajouter crème, vinaigre et assaisonnement; servir avec saucisses tranchées."],"place":{"slug":"ch-vaud","name":"Canton de Vaud","type":"region","lat":46.618,"lng":6.672,"summary":"Canton suisse associé au papet vaudois et aux malakoffs."},"photo":{"file":"File:Papet et saucisse aux choux.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Papet_et_saucisse_aux_choux.jpg/500px-Papet_et_saucisse_aux_choux.jpg","page":"https://commons.wikimedia.org/wiki/File:Papet_et_saucisse_aux_choux.jpg","author":"Clément Bucco-Lechat","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"malakoffs-ch","country":"CH","original":"Malakoffs","title":"Malakoffs (beignets suisses au fromage)","en":"Malakoffs (Swiss cheese fritters)","es":"Malakoffs (buñuelos suizos de queso)","desc":"Beignets vaudois de fromage sur une base de pain; adaptation domestique frite en petites portions.","cat":"Entrée","diff":"medium","prep":25,"cook":15,"serv":8,"reference":"https://en.wikipedia.org/wiki/Malakoff_%28food%29","auth":"adapted","ing":[["Gruyère",300,"g",null],["Pain blanc",8,"tranches fines",null],["Farine",30,"g",null],["Œufs",2,null,null],["Vin blanc",60,"ml",null],["Ail",1,"gousse",null],["Muscade",0.25,"c. à thé",null],["Poivre",0.25,"c. à thé",null],["Huile de friture",800,"ml",null]],"steps":["Râper le fromage. Mélanger avec farine, œufs, vin, ail finement râpé, muscade et poivre.","Découper les tranches de pain en disques de 2 1/2 pouces.","Répartir la préparation au fromage en dômes sur les disques, en pressant pour qu’elle adhère. Réfrigérer 20 minutes.","Chauffer l’huile à 170 °C. Déposer délicatement les beignets, garniture vers le bas, puis retourner lorsque la croûte commence à se former.","Cuire environ 3 à 4 minutes au total, jusqu’à dorure. Égoutter et servir immédiatement avec une salade."],"place":{"slug":"ch-vaud","name":"Canton de Vaud","type":"region","lat":46.618,"lng":6.672,"summary":"Canton suisse associé au papet vaudois et aux malakoffs."},"photo":{"file":"File:Deux malakoffs.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Deux_malakoffs.jpg/500px-Deux_malakoffs.jpg","page":"https://commons.wikimedia.org/wiki/File:Deux_malakoffs.jpg","author":"Dzamlo","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"rueblitorte-ch","country":"CH","original":"Rüeblitorte","title":"Rüeblitorte (gâteau suisse aux carottes)","en":"Rüeblitorte (Swiss carrot cake)","es":"Rüeblitorte (pastel suizo de zanahoria)","desc":"Gâteau suisse aux carottes et amandes, associé à l’Argovie; glaçage léger au citron.","cat":"Dessert","diff":"medium","prep":30,"cook":45,"serv":10,"reference":"https://en.wikipedia.org/wiki/R%C3%BCeblitorte","auth":"adapted","ing":[["Carottes râpées",250,"g",null],["Poudre d’amandes",250,"g",null],["Œufs",4,null,null],["Sucre",180,"g",null],["Farine",60,"g",null],["Poudre à pâte",1,"c. à thé",null],["Zeste de citron",1,"c. à thé",null],["Jus de citron",2,"c. à soupe",null],["Sucre glace",150,"g",null],["Sel",0.25,"c. à thé",null]],"steps":["Séparer les œufs. Battre jaunes et sucre jusqu’à pâleur, puis ajouter carottes, amandes et zeste.","Mélanger farine et poudre à pâte, puis incorporer à la préparation.","Monter les blancs avec le sel jusqu’à pics fermes et les incorporer délicatement en deux fois.","Verser dans un moule chemisé de 8 pouces. Cuire à 175 °C 40 à 45 minutes jusqu’à cure-dent propre.","Refroidir complètement. Mélanger sucre glace et citron pour un glaçage épais, l’étaler et laisser prendre avant de servir."],"photo":{"file":"File:Rueblitorte.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Rueblitorte.jpg/500px-Rueblitorte.jpg","page":"https://commons.wikimedia.org/wiki/File:Rueblitorte.jpg","author":"http://rezeptewiki.org/wiki/Benutzer:At_u","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"bienenstich-de","country":"DE","original":"Bienenstich","title":"Bienenstich (gâteau allemand aux amandes et crème)","en":"Bienenstich (German almond and custard cake)","es":"Bienenstich (pastel alemán de almendras y crema)","desc":"Gâteau allemand de pâte levée, crème vanillée et croûte d’amandes caramélisées au miel.","cat":"Dessert","diff":"hard","prep":45,"cook":30,"serv":10,"reference":"https://en.wikipedia.org/wiki/Bienenstich","auth":"adapted","ing":[["Farine",300,"g",null],["Lait pour pâte",150,"ml",null],["Levure sèche",5,"g",null],["Sucre pour pâte",50,"g",null],["Beurre pour pâte",50,"g",null],["Œuf",1,null,null],["Amandes effilées",100,"g",null],["Beurre pour dessus",60,"g",null],["Miel",60,"g",null],["Crème pour dessus",30,"ml",null],["Lait pour crème",400,"ml",null],["Jaunes d’œufs",3,null,null],["Sucre pour crème",70,"g",null],["Fécule",35,"g",null],["Vanille",1,"c. à thé",null]],"steps":["Pétrir farine, lait tiède, levure, sucre de pâte, œuf et beurre ramolli 10 minutes. Couvrir et laisser lever 1 heure.","Étaler dans un moule de 9 pouces. Chauffer beurre du dessus, miel et crème 1 minute, ajouter les amandes et laisser tiédir.","Répartir les amandes sur la pâte, laisser lever 30 minutes puis cuire à 180 °C 25 à 30 minutes. Refroidir complètement.","Cuire lait, jaunes, sucre de crème et fécule en remuant jusqu’à ébullition, puis 1 minute. Ajouter vanille, filmer au contact et refroidir.","Couper le gâteau horizontalement; découper d’abord la couche supérieure en 10 pointes. Garnir la base de crème, reposer les pointes et réfrigérer 2 heures."],"photo":{"file":"File:Bienenstich.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Bienenstich.jpg/500px-Bienenstich.jpg","page":"https://commons.wikimedia.org/wiki/File:Bienenstich.jpg","author":"Mufi69","license":"CC BY-SA 2.0 de","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/de/deed.en","source":"Wikimedia Commons"}},{"slug":"quarkkeulchen-de","country":"DE","original":"Quarkkeulchen","title":"Quarkkeulchen (galettes saxonnes au fromage et pommes de terre)","en":"Quarkkeulchen (Saxon quark and potato cakes)","es":"Quarkkeulchen (tortitas sajonas de queso y patata)","desc":"Galettes sucrées de Saxe au quark et pommes de terre, dorées à la poêle et souvent servies avec compote.","cat":"Dessert","diff":"medium","prep":25,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Quarkkeulchen","auth":"adapted","ing":[["Pommes de terre",500,"g",null],["Quark égoutté",250,"g",null],["Farine",80,"g",null],["Œuf",1,null,null],["Sucre",40,"g",null],["Raisins secs",50,"g",null],["Zeste de citron",1,"c. à thé",null],["Beurre",30,"g",null],["Huile",1,"c. à soupe",null],["Sel",0.25,"c. à thé",null]],"steps":["Cuire les pommes de terre pelées dans l’eau 20 minutes. Égoutter, écraser et laisser refroidir pour ne pas chauffer l’œuf.","Mélanger avec quark, farine, œuf, sucre, raisins, zeste et sel.","Avec les mains farinées, former 10 petites galettes de 1/2 pouce d’épaisseur.","Les dorer dans beurre et huile à feu moyen doux 3 à 4 minutes par face, jusqu’à centres pris.","Servir tièdes avec une compote préparée séparément. Si la pâte est très humide, mieux égoutter le quark plutôt que multiplier la farine."],"place":{"slug":"de-saxony","name":"Saxe","type":"region","lat":51.027,"lng":13.358,"summary":"Région allemande associée aux Quarkkeulchen."},"photo":{"file":"File:Quarkkeulchen.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/da/Quarkkeulchen.jpg","page":"https://commons.wikimedia.org/wiki/File:Quarkkeulchen.jpg","author":"de:User:Schmidti","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"semmelknodel-de","country":"DE","original":"Semmelknodel","title":"Semmelknödel (boulettes allemandes de pain)","en":"Semmelknödel (German bread dumplings)","es":"Semmelknödel (bolas alemanas de pan)","desc":"Boulettes de pain rassis liées au lait et aux œufs, pochées doucement; préparation également courante en Autriche.","cat":"Accompagnement","diff":"medium","prep":25,"cook":20,"serv":6,"reference":"https://en.wikipedia.org/wiki/Semmelkn%C3%B6del","auth":"adapted","ing":[["Pain blanc rassis",300,"g",null],["Lait",250,"ml",null],["Œufs",2,null,null],["Oignon",1,null,null],["Beurre",25,"g",null],["Persil",20,"g",null],["Farine",1,"c. à soupe","seulement si nécessaire"],["Sel",0.5,"c. à thé",null],["Muscade",0.25,"c. à thé",null]],"steps":["Couper le pain en petits cubes et verser le lait tiède. Laisser imbiber 15 minutes.","Attendrir l’oignon finement haché dans le beurre 5 minutes, puis ajouter au pain avec persil, œufs, sel et muscade.","Mélanger sans réduire en purée. Former une petite boulette test; ajouter la farine uniquement si le mélange ne tient pas.","Former 6 grosses boulettes avec les mains humides. Pocher dans de l’eau à peine frémissante 15 à 20 minutes, sans forte ébullition.","Sortir délicatement et servir avec sauce ou mijoté préparés séparément."],"photo":{"file":"File:Semmelknödel.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Semmelkn%C3%B6del.jpg/500px-Semmelkn%C3%B6del.jpg","page":"https://commons.wikimedia.org/wiki/File:Semmelkn%C3%B6del.jpg","author":"Kobako","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"Wikimedia Commons"}},{"slug":"zwiebelkuchen-de","country":"DE","original":"Zwiebelkuchen","title":"Zwiebelkuchen (tarte allemande aux oignons)","en":"Zwiebelkuchen (German onion tart)","es":"Zwiebelkuchen (tarta alemana de cebolla)","desc":"Tarte allemande salée aux oignons, lardons, crème et carvi sur une pâte levée.","cat":"Plat principal","diff":"medium","prep":35,"cook":40,"serv":8,"reference":"https://en.wikipedia.org/wiki/Zwiebelkuchen","auth":"adapted","ing":[["Farine",300,"g",null],["Lait pour pâte",150,"ml",null],["Levure sèche",5,"g",null],["Beurre pour pâte",40,"g",null],["Oignons",800,"g",null],["Lardons",150,"g",null],["Crème sure",200,"g",null],["Œufs",2,null,null],["Carvi",1,"c. à thé",null],["Beurre pour oignons",20,"g",null],["Sel",0.75,"c. à thé",null]],"steps":["Pétrir farine, lait tiède, levure, beurre de pâte et la moitié du sel. Laisser lever 1 heure.","Dorer les lardons, puis cuire les oignons émincés dans leur gras avec le beurre 15 à 20 minutes, sans les brûler.","Laisser tiédir et mélanger avec crème sure, œufs, carvi et sel restant.","Étaler la pâte dans un moule de 10 pouces et garnir avec les oignons.","Cuire à 190 °C 35 à 40 minutes, jusqu’à pâte dorée et garniture prise. Laisser reposer 10 minutes avant de couper."],"photo":{"file":"File:Zwiebelkuchen 1.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Zwiebelkuchen_1.JPG/500px-Zwiebelkuchen_1.JPG","page":"https://commons.wikimedia.org/wiki/File:Zwiebelkuchen_1.JPG","author":"Biezl","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"dampfnudel-de","country":"DE","original":"Dampfnudel","title":"Dampfnudeln (brioches allemandes cuites à vapeur)","en":"Dampfnudeln (German steamed buns)","es":"Dampfnudeln (bollos alemanes al vapor)","desc":"Brioches levées allemandes, cuites à couvert dans une poêle avec lait et beurre jusqu’à fond doré.","cat":"Dessert","diff":"medium","prep":30,"cook":30,"serv":8,"reference":"https://en.wikipedia.org/wiki/Dampfnudel","auth":"adapted","ing":[["Farine",400,"g",null],["Lait pour pâte",200,"ml",null],["Levure sèche",7,"g",null],["Sucre pour pâte",50,"g",null],["Beurre pour pâte",50,"g",null],["Œuf",1,null,null],["Sel",0.5,"c. à thé",null],["Lait pour cuisson",200,"ml",null],["Beurre pour cuisson",40,"g",null],["Sucre pour cuisson",20,"g",null]],"steps":["Pétrir farine, lait tiède, levure, sucre de pâte, beurre ramolli, œuf et sel 10 minutes. Laisser lever 1 heure.","Former 8 boules et laisser reposer 30 minutes sous un linge.","Dans une grande poêle profonde avec couvercle, chauffer lait de cuisson, beurre et sucre. Déposer les boules en laissant un peu d’espace.","Couvrir et cuire à feu très doux 25 à 30 minutes sans ouvrir, jusqu’à cuisson vapeur et légère croûte dorée dessous.","Couper le feu avant d’ouvrir doucement le couvercle pour éviter que l’eau condensée tombe sur les brioches. Servir chaudes avec un accompagnement choisi."],"photo":{"file":"File:BDampfnudeln WPB.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/BDampfnudeln_WPB.jpg/500px-BDampfnudeln_WPB.jpg","page":"https://commons.wikimedia.org/wiki/File:BDampfnudeln_WPB.jpg","author":"Oliver s. at German Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"kartoffelsalat-de","country":"DE","original":"Kartoffelsalat","title":"Kartoffelsalat au bouillon (salade allemande de pommes de terre)","en":"Broth-dressed German potato salad","es":"Kartoffelsalat (ensalada alemana de patata con caldo)","desc":"Salade de pommes de terre du sud de l’Allemagne, assaisonnée avec bouillon, vinaigre et huile, sans mayonnaise.","cat":"Salade","diff":"easy","prep":20,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kartoffelsalat","auth":"adapted","ing":[["Pommes de terre à chair ferme",900,"g",null],["Oignon",1,null,null],["Bouillon de légumes",200,"ml",null],["Vinaigre de vin",3,"c. à soupe",null],["Huile",3,"c. à soupe",null],["Moutarde",1,"c. à thé",null],["Ciboulette",15,"g",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Cuire les pommes de terre entières avec leur peau dans l’eau 20 à 25 minutes, jusqu’à tendreté sans désagrégation.","Tiédir, peler et couper en rondelles fines. Placer dans un grand saladier.","Faire frémir le bouillon avec oignon finement haché, vinaigre, moutarde, sel et poivre 3 minutes.","Verser sur les pommes de terre encore tièdes et mélanger délicatement. Laisser absorber 20 minutes.","Ajouter huile et ciboulette, goûter et servir tiède ou refroidie; réfrigérer si elle n’est pas servie rapidement."],"photo":{"file":"File:Kartoffelsalat.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Kartoffelsalat.jpg/500px-Kartoffelsalat.jpg","page":"https://commons.wikimedia.org/wiki/File:Kartoffelsalat.jpg","author":"Kobako","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"Wikimedia Commons"}},{"slug":"marillenknodel-at","country":"AT","original":"Marillenknodel","title":"Marillenknödel (boulettes autrichiennes aux abricots)","en":"Marillenknödel (Austrian apricot dumplings)","es":"Marillenknödel (bolas austriacas de albaricoque)","desc":"Abricots entiers enfermés dans une pâte au quark, pochés puis roulés dans une chapelure beurrée.","cat":"Dessert","diff":"medium","prep":35,"cook":20,"serv":8,"reference":"https://en.wikipedia.org/wiki/Marillenkn%C3%B6del","auth":"adapted","ing":[["Abricots",8,null,null],["Quark égoutté",250,"g",null],["Farine",130,"g",null],["Beurre pour pâte",40,"g",null],["Œuf",1,null,null],["Sucre",40,"g",null],["Chapelure",100,"g",null],["Beurre pour chapelure",60,"g",null],["Sel",0.25,"c. à thé",null],["Cannelle",0.5,"c. à thé",null]],"steps":["Mélanger quark, beurre de pâte ramolli, œuf, farine et sel. Réfrigérer 30 minutes.","Dénoyauter les abricots sans séparer complètement leurs moitiés.","Diviser la pâte en 8 portions et enfermer un abricot dans chacune, en fermant tous les joints.","Pocher à frémissement doux 12 à 15 minutes, jusqu’à pâte cuite; ne pas faire bouillir fortement.","Dorer la chapelure dans le beurre, puis ajouter sucre et cannelle. Rouler les boulettes égouttées dans ce mélange et servir."],"photo":{"file":"File:140802 Marillenknödel (14741213900).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/140802_Marillenkn%C3%B6del_%2814741213900%29.jpg/500px-140802_Marillenkn%C3%B6del_%2814741213900%29.jpg","page":"https://commons.wikimedia.org/wiki/File:140802_Marillenkn%C3%B6del_(14741213900).jpg","author":"weisserstier from Wien, Austria","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"linzer-torte-at","country":"AT","original":"Linzer torte","title":"Linzer torte (tarte autrichienne aux noix et confiture)","en":"Linzer torte (Austrian nut and jam tart)","es":"Linzer torte (tarta austriaca de frutos secos y mermelada)","desc":"Tarte autrichienne à pâte aux noisettes, garnie de confiture de groseilles ou framboises sous un treillis.","cat":"Dessert","diff":"medium","prep":35,"cook":35,"serv":10,"reference":"https://en.wikipedia.org/wiki/Linzer_torte","auth":"adapted","ing":[["Farine",200,"g",null],["Noisettes moulues",150,"g",null],["Beurre",160,"g",null],["Sucre",120,"g",null],["Œuf",1,null,null],["Cannelle",1,"c. à thé",null],["Zeste de citron",1,"c. à thé",null],["Confiture de groseilles",250,"g","ou framboises"],["Sel",0.25,"c. à thé",null]],"steps":["Mélanger farine, noisettes, sucre, cannelle, zeste et sel. Sabler avec le beurre, puis ajouter l’œuf.","Rassembler la pâte et réfrigérer 30 minutes pour la raffermir.","Presser les deux tiers dans un moule de 9 pouces, en créant un rebord. Étaler la confiture.","Former des bandes avec le reste et les disposer en treillis, sans couvrir toute la garniture.","Cuire à 175 °C 35 à 40 minutes jusqu’à pâte dorée. Refroidir complètement; le gâteau se tranche mieux après une nuit de repos."],"place":{"slug":"at-linz","name":"Linz","type":"city","lat":48.3069,"lng":14.2858,"summary":"Ville autrichienne associée à la Linzer Torte."},"photo":{"file":"File:Linzer Torte at Hawthorn, Victoria bakery.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Linzer_Torte_at_Hawthorn%2C_Victoria_bakery.jpg/500px-Linzer_Torte_at_Hawthorn%2C_Victoria_bakery.jpg","page":"https://commons.wikimedia.org/wiki/File:Linzer_Torte_at_Hawthorn,_Victoria_bakery.jpg","author":"Alpha","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"buchteln-at","country":"AT","original":"Buchteln","title":"Buchteln (brioches autrichiennes fourrées)","en":"Buchteln (Austrian jam-filled buns)","es":"Buchteln (bollos austriacos rellenos)","desc":"Brioches d’Europe centrale très présentes en Autriche, farcies de confiture et cuites serrées dans un plat.","cat":"Dessert","diff":"medium","prep":35,"cook":30,"serv":12,"reference":"https://en.wikipedia.org/wiki/Buchteln","auth":"adapted","ing":[["Farine",450,"g",null],["Lait",220,"ml",null],["Levure sèche",7,"g",null],["Sucre",60,"g",null],["Beurre pour pâte",70,"g",null],["Œuf",1,null,null],["Confiture de prune",180,"g",null],["Beurre pour plat",30,"g",null],["Sel",0.5,"c. à thé",null]],"steps":["Pétrir farine, lait tiède, levure, sucre, œuf, sel et beurre de pâte ramolli 10 minutes. Couvrir et laisser doubler de volume.","Diviser en 12 portions et aplatir chacune dans la paume.","Déposer une cuillère de confiture au centre et refermer soigneusement sans la laisser toucher les joints.","Badigeonner de beurre fondu et disposer joint dessous dans un plat de 9 sur 13 pouces. Laisser lever 40 minutes.","Cuire à 180 °C 25 à 30 minutes jusqu’à dessus doré et centre cuit; laisser tiédir avant de séparer."],"photo":{"file":"File:Buchteln.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/c4/Buchteln.jpg","page":"https://commons.wikimedia.org/wiki/File:Buchteln.jpg","author":"Gerhard Juengling at de.wikipedia","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"kluski-slaskie-pl","country":"PL","original":"Kluski slaskie","title":"Kluski śląskie (boulettes silésiennes de pommes de terre)","en":"Kluski śląskie (Silesian potato dumplings)","es":"Kluski śląskie (bolas silesianas de patata)","desc":"Boulettes silésiennes de pommes de terre et fécule, reconnaissables à leur petit creux central.","cat":"Accompagnement","diff":"medium","prep":30,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Kluski_%C5%9Bl%C4%85skie","auth":"adapted","ing":[["Pommes de terre",800,"g",null],["Fécule de pomme de terre",200,"g",null],["Œuf",1,null,null],["Sel",0.5,"c. à thé",null]],"steps":["Peler et cuire les pommes de terre dans l’eau 20 minutes. Bien égoutter, écraser finement et laisser tiédir.","Ajouter fécule, œuf et sel; rassembler en pâte souple sans long pétrissage.","Former des boulettes de 1 1/2 pouce et creuser leur centre avec le pouce.","Pocher par fournées dans de l’eau frémissante salée. Dès qu’elles remontent, poursuivre environ 3 minutes.","Égoutter avec une écumoire et servir avec une sauce préparée séparément. Tester une première boulette avant de cuire tout le lot."],"photo":{"file":"File:Kluski śląskie 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/60/Kluski_%C5%9Bl%C4%85skie_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Kluski_%C5%9Bl%C4%85skie_01.jpg","author":"Ewkaa","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"sernik-pl","country":"PL","original":"Sernik","title":"Sernik (gâteau polonais au fromage)","en":"Sernik (Polish curd cheesecake)","es":"Sernik (tarta polaca de queso)","desc":"Gâteau polonais au twaróg; adaptation au quark bien égoutté si le fromage polonais est introuvable. Cette version repose sur une base sablée.","cat":"Dessert","diff":"medium","prep":35,"cook":72,"serv":10,"reference":"https://en.wikipedia.org/wiki/Cheesecake#Poland","auth":"adapted","ing":[["Twaróg finement moulu",750,"g","ou quark égoutté"],["Œufs",4,null,null],["Sucre",180,"g",null],["Beurre",100,"g",null],["Fécule de maïs",40,"g",null],["Vanille",1,"c. à thé",null],["Zeste de citron",1,"c. à thé",null],["Sel",0.25,"c. à thé",null],["Farine pour la base",150,"g",null],["Beurre pour la base",70,"g",null],["Sucre pour la base",40,"g",null],["Eau froide",2,"c. à soupe",null]],"steps":["Sabler la farine de la base avec son beurre et son sucre, ajouter l’eau froide et réunir en pâte. Étaler au fond du moule de 9 pouces et précuire 12 minutes à 180 °C; laisser tiédir avant de garnir.","Séparer les œufs. Battre beurre et sucre, puis incorporer les jaunes un à un.","Ajouter fromage, fécule, vanille et zeste; mélanger jusqu’à texture lisse.","Monter les blancs avec le sel et les incorporer doucement, sans trop aérer.","Verser dans un moule chemisé de 9 pouces. Cuire à 160 °C 55 à 65 minutes, jusqu’à bords pris et centre légèrement souple.","Éteindre le four, entrouvrir et laisser refroidir 30 minutes. Refroidir complètement puis réfrigérer au moins 4 heures avant de couper."],"photo":{"file":"File:Sernik cheesecake (1).JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Sernik_cheesecake_%281%29.JPG/500px-Sernik_cheesecake_%281%29.JPG","page":"https://commons.wikimedia.org/wiki/File:Sernik_cheesecake_(1).JPG","author":"Alina Zienowicz (Ala_z)","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"racuchy-pl","country":"PL","original":"Racuchy","title":"Racuchy aux pommes (galettes polonaises)","en":"Apple racuchy (Polish pancakes)","es":"Racuchy de manzana (tortitas polacas)","desc":"Galettes polonaises aux morceaux de pommes; adaptation rapide à la poudre à pâte.","cat":"Dessert","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Racuchy","auth":"adapted","ing":[["Farine",200,"g",null],["Lait",180,"ml",null],["Œuf",1,null,null],["Pommes",2,null,null],["Sucre",25,"g",null],["Poudre à pâte",1.5,"c. à thé",null],["Huile",3,"c. à soupe",null],["Cannelle",0.5,"c. à thé",null],["Sel",0.25,"c. à thé",null]],"steps":["Mélanger farine, sucre, poudre à pâte, cannelle et sel.","Fouetter lait et œuf, puis incorporer aux ingrédients secs sans trop battre.","Peler les pommes, les couper en petits morceaux et les ajouter à la pâte.","Déposer de petites cuillerées dans une poêle huilée à feu moyen doux. Cuire 2 à 3 minutes par face, jusqu’à dorure et centre cuit.","Égoutter légèrement et servir tiède; ajouter du sucre glace seulement si désiré."],"photo":{"file":"File:Racuchy.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Racuchy.JPG/500px-Racuchy.JPG","page":"https://commons.wikimedia.org/wiki/File:Racuchy.JPG","author":"Pilecka","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"mizeria-pl","country":"PL","original":"Mizeria","title":"Mizeria (salade polonaise de concombre)","en":"Mizeria (Polish cucumber salad)","es":"Mizeria (ensalada polaca de pepino)","desc":"Salade polonaise de concombre à la crème sure et à l’aneth.","cat":"Salade","diff":"easy","prep":15,"cook":0,"serv":4,"reference":"https://en.wikipedia.org/wiki/Mizeria","auth":"adapted","ing":[["Concombres",2,null,null],["Crème sure",150,"g",null],["Aneth",15,"g",null],["Jus de citron",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Sucre",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null]],"steps":["Peler les concombres si leur peau est épaisse et les couper en rondelles très fines.","Mélanger avec le sel et laisser dégorger 15 minutes dans une passoire.","Presser délicatement pour enlever l’eau, sans écraser complètement les rondelles.","Mélanger crème sure, citron, sucre, poivre et aneth haché, puis incorporer les concombres.","Réfrigérer 15 minutes et servir le jour même, pour garder le concombre croquant."],"photo":{"file":"File:Mizeria.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Mizeria.jpg/500px-Mizeria.jpg","page":"https://commons.wikimedia.org/wiki/File:Mizeria.jpg","author":"Mariuszjbie","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"mamaliga-ro","country":"RO","original":"Mamaliga","title":"Mămăligă (bouillie roumaine de maïs)","en":"Mămăligă (Romanian cornmeal porridge)","es":"Mămăligă (gachas rumanas de maíz)","desc":"Préparation roumaine de semoule de maïs, assez ferme pour être servie en portions; les garnitures restent au choix.","cat":"Accompagnement","diff":"easy","prep":10,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/M%C4%83m%C4%83lig%C4%83","auth":"adapted","ing":[["Semoule de maïs",250,"g",null],["Eau",1000,"ml",null],["Sel",1,"c. à thé",null],["Beurre",25,"g",null]],"steps":["Porter l’eau et le sel à frémissement dans une casserole épaisse.","Verser la semoule en pluie en fouettant continuellement pour éviter les grumeaux.","Baisser le feu et cuire 25 à 30 minutes en remuant souvent avec une cuillère; suivre le temps indiqué pour la semoule utilisée.","Ajouter le beurre lorsque les grains sont tendres et la pâte se détache des parois.","Servir souple à la cuillère ou verser dans un plat humide et laisser reposer quelques minutes pour découper des portions."],"photo":{"file":"File:Mamaliga.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Mamaliga.jpg","page":"https://commons.wikimedia.org/wiki/File:Mamaliga.jpg","author":"","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"chokladbollar-se","country":"SE","original":"Chokladbollar","title":"Chokladbollar (boules suédoises cacao et avoine)","en":"Chokladbollar (Swedish chocolate oat balls)","es":"Chokladbollar (bolas suecas de cacao y avena)","desc":"Confiseries suédoises sans cuisson à l’avoine, cacao et café, roulées dans la noix de coco.","cat":"Dessert","diff":"easy","prep":20,"cook":0,"serv":20,"reference":"https://en.wikipedia.org/wiki/Chokladboll","auth":"adapted","ing":[["Flocons d’avoine",180,"g",null],["Beurre",100,"g",null],["Sucre",90,"g",null],["Cacao",25,"g",null],["Café refroidi",3,"c. à soupe",null],["Vanille",1,"c. à thé",null],["Noix de coco râpée",60,"g",null]],"steps":["Mixer brièvement les flocons pour garder une texture fine sans les réduire entièrement en farine.","Battre beurre ramolli et sucre, puis ajouter cacao, café et vanille.","Incorporer l’avoine et mélanger; réfrigérer 15 minutes si la préparation est trop souple.","Former 20 boules et les rouler dans la noix de coco.","Réfrigérer au moins 1 heure avant de servir. Garder au frais dans un contenant fermé."],"photo":{"file":"File:Bollar.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/b/b1/Bollar.JPG","page":"https://commons.wikimedia.org/wiki/File:Bollar.JPG","author":"Stefan Weisenbacher","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"Wikimedia Commons"}},{"slug":"gubbrora-se","country":"SE","original":"Gubbrora","title":"Gubbröra (salade suédoise œufs et poisson mariné)","en":"Gubbröra (Swedish egg and cured fish salad)","es":"Gubbröra (ensalada sueca de huevo y pescado marinado)","desc":"Préparation suédoise d’œufs durs, pommes de terre et ansjovis suédois; ce poisson épicé diffère des anchois méditerranéens.","cat":"Entrée","diff":"easy","prep":20,"cook":20,"serv":4,"reference":"https://www.swedishfood.com/appetisers/gubbrora","auth":"adapted","ing":[["Œufs",4,null,null],["Pommes de terre",250,"g",null],["Ansjovis suédois",100,"g","sprats marinés épicés"],["Crème sure",100,"g",null],["Oignon rouge",0.5,null,null],["Aneth",15,"g",null],["Ciboulette",10,"g",null],["Poivre",0.25,"c. à thé",null]],"steps":["Cuire les pommes de terre entières 15 à 20 minutes jusqu’à tendreté, puis refroidir et couper en petits dés.","Cuire les œufs 10 minutes, les refroidir dans l’eau puis les écaler et les hacher.","Égoutter les sprats et les couper en petits morceaux. Hacher finement oignon et herbes.","Mélanger tous les ingrédients délicatement avec crème sure et poivre; goûter avant d’ajouter éventuellement du sel.","Réfrigérer 30 minutes et servir sur du pain de seigle ou à côté."],"photo":{"file":"File:Gubbröra.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Gubbr%C3%B6ra.jpg","page":"https://commons.wikimedia.org/wiki/File:Gubbr%C3%B6ra.jpg","author":"Ascilto","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"rommegrot-no","country":"NO","original":"Rommegrot","title":"Rømmegrøt (bouillie norvégienne à la crème sure)","en":"Rømmegrøt (Norwegian sour cream porridge)","es":"Rømmegrøt (gachas noruegas de crema agria)","desc":"Bouillie norvégienne riche à la crème sure, farine et lait, servie avec cannelle et sucre.","cat":"Dessert","diff":"medium","prep":10,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/R%C3%B8mmegr%C3%B8t","auth":"adapted","ing":[["Crème sure entière",500,"g",null],["Farine",100,"g",null],["Lait",400,"ml",null],["Sel",0.25,"c. à thé",null],["Sucre",40,"g",null],["Cannelle",1,"c. à thé",null],["Beurre",20,"g","facultatif si la crème libère peu de gras"],["Raisins secs",30,"g","facultatifs, pour servir comme sur la photo"]],"steps":["Faire frémir doucement la crème sure dans une casserole épaisse 5 minutes, en remuant.","Ajouter la moitié de la farine en pluie et fouetter. Si du beurre se sépare, le prélever et le réserver pour servir.","Incorporer le reste de la farine, puis le lait chaud progressivement pour éviter les grumeaux.","Cuire à feu très doux 8 à 10 minutes, jusqu’à préparation lisse et farine cuite. Ajouter le sel.","Servir avec sucre, cannelle et beurre réservé; utiliser le beurre prévu si aucune séparation de gras ne s’est produite."],"photo":{"file":"File:Römmegröt.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/0a/R%C3%B6mmegr%C3%B6t.jpg","page":"https://commons.wikimedia.org/wiki/File:R%C3%B6mmegr%C3%B6t.jpg","author":"Tomas Eklund","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"lihapiirakka-fi","country":"FI","original":"Lihapiirakka","title":"Lihapiirakka (chaussons finlandais frits)","en":"Lihapiirakka (Finnish fried meat pies)","es":"Lihapiirakka (empanadas finlandesas fritas)","desc":"Chaussons finlandais de pâte levée farcis de bœuf haché et riz; les accompagnements sont facultatifs.","cat":"Plat principal","diff":"medium","prep":45,"cook":25,"serv":8,"reference":"https://en.wikipedia.org/wiki/Lihapiirakka","auth":"adapted","ing":[["Farine",400,"g",null],["Lait",220,"ml",null],["Levure sèche",7,"g",null],["Sucre",1,"c. à soupe",null],["Huile pour pâte",2,"c. à soupe",null],["Sel",1,"c. à thé",null],["Bœuf haché",350,"g",null],["Riz cru",70,"g",null],["Oignon",1,null,null],["Poivre",0.5,"c. à thé",null],["Huile de friture",1000,"ml",null]],"steps":["Pétrir farine, lait tiède, levure, sucre, huile de pâte et la moitié du sel; laisser lever 1 heure.","Cuire le riz dans l’eau selon son emballage. Dorer l’oignon et le bœuf ensemble, jusqu’à viande à 71 °C; ajouter riz, poivre et sel restant, puis refroidir.","Diviser la pâte en 8 portions, les abaisser en ovales et répartir la farce froide.","Plier en chaussons, fermer soigneusement les bords et laisser reposer 20 minutes.","Frire à 165 °C 3 à 4 minutes par face, jusqu’à pâte dorée et cuite à cœur. Égoutter sur une grille."],"photo":{"file":"File:Lihapiirakka.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/92/Lihapiirakka.jpg","page":"https://commons.wikimedia.org/wiki/File:Lihapiirakka.jpg","author":"Mika (Mika83)","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"taiyaki-jp","country":"JP","original":"Taiyaki","title":"Taiyaki (gâteaux japonais en forme de poisson)","en":"Taiyaki (Japanese fish-shaped cakes)","es":"Taiyaki (pastelitos japoneses en forma de pez)","desc":"Gâteaux japonais cuits dans un moule en forme de poisson, garnis de pâte sucrée de haricots rouges.","cat":"Dessert","diff":"medium","prep":20,"cook":20,"serv":6,"reference":"https://en.wikipedia.org/wiki/Taiyaki","auth":"adapted","ing":[["Farine",150,"g",null],["Poudre à pâte",1,"c. à thé",null],["Sucre",30,"g",null],["Œuf",1,null,null],["Lait",180,"ml",null],["Pâte anko",240,"g",null],["Huile",1,"c. à soupe",null]],"steps":["Mélanger farine, poudre à pâte et sucre. Ajouter œuf battu et lait pour former une pâte lisse; laisser reposer 15 minutes.","Chauffer le moule à taiyaki et huiler légèrement ses cavités.","Verser une fine couche de pâte, ajouter 40 g d’anko sans toucher les bords, puis couvrir d’un peu de pâte.","Fermer le moule et cuire à feu moyen doux environ 3 minutes par face, en suivant les indications du moule.","Démouler quand les gâteaux sont dorés et la pâte cuite. Servir tièdes; un moule spécifique est nécessaire pour cette présentation."],"photo":{"file":"File:Taiyaki.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/35/Taiyaki.jpg","page":"https://commons.wikimedia.org/wiki/File:Taiyaki.jpg","author":"Toto-tarou","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"tangyuan-cn","country":"CN","original":"Tangyuan","title":"Tangyuan (boulettes chinoises au sésame noir)","en":"Tangyuan (Chinese black sesame rice balls)","es":"Tangyuan (bolas chinas de arroz con sésamo negro)","desc":"Boulettes chinoises de riz gluant farcies au sésame noir, servies dans un sirop léger au gingembre. La photo inclut des boules roses; une goutte de colorant alimentaire peut colorer une partie de la pâte.","cat":"Dessert","diff":"medium","prep":40,"cook":15,"serv":6,"reference":"https://en.wikipedia.org/wiki/Tangyuan","auth":"adapted","ing":[["Farine de riz gluant",200,"g",null],["Eau tiède pour pâte",150,"ml",null],["Sésame noir",80,"g",null],["Sucre pour farce",50,"g",null],["Beurre",40,"g",null],["Eau pour sirop",1200,"ml",null],["Sucre pour sirop",80,"g",null],["Gingembre",20,"g",null]],"steps":["Griller le sésame brièvement à sec, refroidir et moudre avec le sucre. Mélanger au beurre ramolli; réfrigérer puis former 18 petites portions.","Ajouter l’eau tiède progressivement à la farine de riz gluant pour obtenir une pâte souple, sans fissures.","Diviser en 18 portions. Envelopper chacune autour d’une boule de farce et fermer soigneusement.","Mijoter eau du sirop, sucre et gingembre tranché 10 minutes. Pocher les boulettes dans une seconde casserole d’eau frémissante 6 à 8 minutes, jusqu’à remontée et pâte cuite.","Répartir les boulettes dans six bols et verser le sirop chaud. Attendre un peu avant de manger, car la farce peut être brûlante."],"photo":{"file":"File:圓仔.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/%E5%9C%93%E4%BB%94.jpg/500px-%E5%9C%93%E4%BB%94.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%9C%93%E4%BB%94.jpg","author":"Sebastian Mary","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"zongzi-cn","country":"CN","original":"Zongzi","title":"Zongzi au porc (riz chinois en feuilles)","en":"Pork zongzi (Chinese leaf-wrapped rice)","es":"Zongzi de cerdo (arroz chino envuelto en hojas)","desc":"Riz gluant chinois farci au porc et champignons, enveloppé dans des feuilles de bambou puis bouilli.","cat":"Plat principal","diff":"hard","prep":60,"cook":150,"serv":8,"reference":"https://en.wikipedia.org/wiki/Zongzi","auth":"adapted","ing":[["Riz gluant",500,"g",null],["Porc désossé",350,"g",null],["Shiitakés séchés",8,null,null],["Feuilles de bambou séchées",24,null,null],["Sauce soja",4,"c. à soupe",null],["Sauce soja foncée",1,"c. à soupe",null],["Sucre",1,"c. à soupe",null],["Cinq-épices",0.5,"c. à thé",null],["Sel",0.5,"c. à thé",null]],"steps":["Tremper riz et feuilles séparément toute une nuit. Réhydrater les champignons 30 minutes; laver soigneusement les feuilles et retirer leurs parties dures.","Couper le porc en morceaux et le mariner avec moitié des sauces, sucre et cinq-épices au frais 1 heure. Assaisonner le riz égoutté avec sauces restantes et sel.","Superposer 2 ou 3 feuilles en cône. Déposer riz, porc et champignon puis encore du riz, sans trop remplir.","Replier les feuilles en paquet fermé et attacher avec de la ficelle alimentaire.","Recouvrir d’eau dans une grande casserole et frémir 2 heures 30, en gardant les paquets immergés. Ouvrir un paquet pour vérifier riz tendre et porc à 74 °C. Refroidir rapidement les portions non mangées."],"photo":{"file":"File:Two Zongzi styles, inside.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Two_Zongzi_styles%2C_inside.jpg/500px-Two_Zongzi_styles%2C_inside.jpg","page":"https://commons.wikimedia.org/wiki/File:Two_Zongzi_styles,_inside.jpg","author":"Dllu","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"shumai-cn","country":"CN","original":"Shumai","title":"Shumai au porc et crevettes (raviolis chinois vapeur)","en":"Pork and shrimp shumai (Chinese steamed dumplings)","es":"Shumai de cerdo y gambas (dumplings chinos al vapor)","desc":"Raviolis chinois ouverts sur le dessus, garnis de porc, crevettes et shiitakés.","cat":"Entrée","diff":"medium","prep":35,"cook":15,"serv":24,"reference":"https://en.wikipedia.org/wiki/Shumai","auth":"adapted","ing":[["Feuilles à shumai",24,null,null],["Porc haché",300,"g",null],["Crevettes crues décortiquées",200,"g",null],["Shiitakés",80,"g",null],["Oignons verts",2,null,null],["Sauce soja",1,"c. à soupe",null],["Huile de sésame",1,"c. à thé",null],["Fécule",1,"c. à soupe",null],["Gingembre",10,"g",null],["Carotte",40,"g",null]],"steps":["Hacher finement crevettes, champignons et oignons verts. Râper le gingembre et couper la carotte en très petits dés.","Mélanger porc, crevettes, champignons, oignons, soja, huile, fécule et gingembre jusqu’à farce liée.","Placer une cuillerée de farce au centre de chaque feuille. Remonter les bords autour sans fermer le dessus, puis aplatir la base.","Ajouter quelques dés de carotte au centre et disposer espacés dans un panier vapeur chemisé de papier perforé.","Cuire au-dessus d’une eau frémissante 12 à 15 minutes, jusqu’à centre à 74 °C et crevettes opaques. Servir chaud."],"photo":{"file":"File:Shumai 20230613 095857.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Shumai_20230613_095857.jpg/500px-Shumai_20230613_095857.jpg","page":"https://commons.wikimedia.org/wiki/File:Shumai_20230613_095857.jpg","author":"Franklin Rainier","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"tteokguk-kr","country":"KR","original":"Tteokguk","title":"Tteokguk (soupe coréenne aux gâteaux de riz)","en":"Tteokguk (Korean rice cake soup)","es":"Tteokguk (sopa coreana de pastelitos de arroz)","desc":"Soupe coréenne de gâteaux de riz tranchés dans un bouillon au bœuf, particulièrement liée au Nouvel An.","cat":"Soupe","diff":"easy","prep":20,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Tteokguk","auth":"adapted","ing":[["Gâteaux de riz tranchés tteok",400,"g",null],["Bœuf en fines tranches",250,"g",null],["Bouillon de bœuf",1400,"ml",null],["Œufs",2,null,null],["Ail",2,"gousses",null],["Oignons verts",3,null,null],["Sauce soja pour soupe",1.5,"c. à soupe",null],["Huile de sésame",1,"c. à thé",null],["Feuille de nori",1,null,null],["Poivre",0.25,"c. à thé",null]],"steps":["Rincer les tteok et les tremper 20 minutes s’ils sont réfrigérés et durs.","Faire revenir le bœuf dans l’huile de sésame 3 minutes, ajouter ail et bouillon puis mijoter 10 minutes.","Battre les œufs et cuire en fine omelette dans une poêle antiadhésive; découper en rubans.","Ajouter les tteok égouttés au bouillon et cuire 5 à 8 minutes, jusqu’à tendreté sans désagrégation. Assaisonner de soja et poivre.","Répartir dans les bols et ajouter omelette, oignons verts émincés et nori en fines bandes."],"photo":{"file":"File:Tteokguk 2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Tteokguk_2.jpg/500px-Tteokguk_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Tteokguk_2.jpg","author":"최광모","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"bossam-kr","country":"KR","original":"Bossam","title":"Bossam (porc coréen à envelopper)","en":"Bossam (Korean boiled pork wraps)","es":"Bossam (cerdo coreano para envolver)","desc":"Porc coréen doucement bouilli puis tranché, servi avec feuilles de laitue, kimchi et ssamjang.","cat":"Plat principal","diff":"easy","prep":20,"cook":75,"serv":6,"reference":"https://en.wikipedia.org/wiki/Bossam","auth":"adapted","ing":[["Poitrine de porc",900,"g",null],["Eau",2000,"ml",null],["Doenjang",2,"c. à soupe",null],["Ail",6,"gousses",null],["Gingembre",30,"g",null],["Oignon",1,null,null],["Poivre en grains",1,"c. à thé",null],["Laitue",12,"feuilles",null],["Kimchi",250,"g",null],["Ssamjang",80,"g",null]],"steps":["Mettre eau, doenjang, ail, gingembre, oignon coupé et poivre dans une casserole et porter au frémissement.","Ajouter le porc et cuire à petits frémissements 60 à 75 minutes, en le retournant si nécessaire.","Vérifier que le porc est tendre et atteint au moins 71 °C. Retirer et laisser reposer 10 minutes avant de couper.","Laver les feuilles de laitue et disposer kimchi et ssamjang dans de petits bols.","Trancher le porc à 1/4 pouce. À table, envelopper une tranche et un peu de condiments dans une feuille; servir sans attendre."],"photo":{"file":"File:Korean.food-Bossam-02.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Korean.food-Bossam-02.jpg/500px-Korean.food-Bossam-02.jpg","page":"https://commons.wikimedia.org/wiki/File:Korean.food-Bossam-02.jpg","author":"by ayustety (a flickr user)","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"ven-pongal-in","country":"IN","original":"Ven pongal","title":"Ven pongal (riz et lentilles du sud de l’Inde)","en":"Ven pongal (South Indian rice and lentil dish)","es":"Ven pongal (arroz y lentejas del sur de la India)","desc":"Préparation salée du sud de l’Inde à riz et haricots mungo décortiqués, parfumée au ghee, poivre et cumin.","cat":"Plat principal","diff":"easy","prep":15,"cook":35,"serv":4,"reference":"https://en.wikipedia.org/wiki/Pongal_%28dish%29","auth":"adapted","ing":[["Riz",180,"g",null],["Mung dal jaune",100,"g",null],["Eau",1000,"ml",null],["Ghee",40,"g",null],["Noix de cajou",30,"g",null],["Gingembre",15,"g",null],["Cumin entier",1,"c. à thé",null],["Poivre noir concassé",0.5,"c. à thé",null],["Feuilles de curry",10,null,null],["Sel",0.75,"c. à thé",null]],"steps":["Griller le mung dal à sec 2 minutes jusqu’à parfum léger, sans le brunir. Rincer avec le riz.","Mettre riz, dal, eau et sel dans une casserole; porter au frémissement et cuire à couvert 25 à 30 minutes, jusqu’à grains très tendres.","Écraser légèrement et ajouter un peu d’eau chaude pour obtenir une texture souple.","Chauffer le ghee dans une petite poêle. Dorer les cajous, puis ajouter cumin, poivre, gingembre haché et feuilles de curry pendant 30 secondes.","Verser ce mélange dans le riz, remuer et servir chaud; attention aux éclaboussures des feuilles dans le gras."],"photo":{"file":"File:Aesthetic Ven Pongal.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Aesthetic_Ven_Pongal.jpg/500px-Aesthetic_Ven_Pongal.jpg","page":"https://commons.wikimedia.org/wiki/File:Aesthetic_Ven_Pongal.jpg","author":"Thamizhpparithi Maari","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"ras-malai-in","country":"IN","original":"Ras malai","title":"Ras malai (palets indiens au lait safrané)","en":"Ras malai (Indian milk dumplings in saffron milk)","es":"Ras malai (dulce indio de queso y leche azafranada)","desc":"Palets de fromage frais pochés puis imbibés de lait sucré au safran et cardamome; préparation distincte du rasgulla servi en sirop.","cat":"Dessert","diff":"hard","prep":45,"cook":40,"serv":8,"reference":"https://en.wikipedia.org/wiki/Ras_malai","auth":"adapted","ing":[["Lait entier pour fromage",1000,"ml",null],["Jus de citron",2,"c. à soupe",null],["Sucre pour sirop",180,"g",null],["Eau pour sirop",1000,"ml",null],["Lait pour crème",700,"ml",null],["Sucre pour crème",60,"g",null],["Cardamome",0.5,"c. à thé",null],["Safran",0.1,"g",null],["Pistaches",25,"g",null]],"steps":["Porter le lait du fromage au frémissement, couper le feu et ajouter le citron. Quand le caillé se sépare, égoutter dans un linge, rincer doucement et presser 30 minutes.","Pétrir le fromage frais égoutté jusqu’à texture lisse et former 8 petits palets sans fissures.","Faire bouillir eau et sucre du sirop. Ajouter les palets, couvrir et cuire à petits bouillons 12 à 15 minutes, jusqu’à gonflement.","Mijoter séparément lait de crème, sucre, safran et cardamome 20 minutes pour réduire légèrement.","Presser très délicatement les palets tiédis et les placer dans le lait parfumé. Réfrigérer au moins 4 heures puis garnir de pistaches."],"photo":{"file":"File:Ras Malai.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Ras_Malai.JPG/500px-Ras_Malai.JPG","page":"https://commons.wikimedia.org/wiki/File:Ras_Malai.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"ketoprak-id","country":"ID","original":"Ketoprak","title":"Ketoprak (tofu indonésien et sauce arachide)","en":"Ketoprak (Indonesian tofu and peanut sauce)","es":"Ketoprak (tofu indonesio con salsa de cacahuete)","desc":"Plat indonésien de tofu, vermicelles, germes de haricots et sauce arachide; adaptation au riz cuit plutôt qu’au lontong.","cat":"Plat principal","diff":"easy","prep":25,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Ketoprak_%28food%29","auth":"adapted","ing":[["Tofu ferme",400,"g",null],["Vermicelles de riz",150,"g",null],["Germes de haricots",200,"g",null],["Riz cuit",300,"g","substitution du lontong"],["Arachides grillées",120,"g",null],["Ail",2,"gousses",null],["Kecap manis",3,"c. à soupe",null],["Jus de tamarin",2,"c. à soupe",null],["Eau chaude",180,"ml",null],["Huile",2,"c. à soupe",null],["Piment",1,null,null]],"steps":["Hydrater les vermicelles selon leur emballage et les égoutter. Blanchir les germes de haricots 2 minutes.","Couper le tofu en cubes et le dorer dans l’huile 8 à 10 minutes, puis égoutter.","Moudre arachides, ail et piment. Ajouter tamarin et eau chaude progressivement pour obtenir une sauce épaisse.","Répartir riz, vermicelles, tofu et germes dans les assiettes.","Napper de sauce arachide et terminer par un filet de kecap manis. Servir dès l’assemblage."],"photo":{"file":"File:Ketoprak Boplo.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Ketoprak_Boplo.JPG/500px-Ketoprak_Boplo.JPG","page":"https://commons.wikimedia.org/wiki/File:Ketoprak_Boplo.JPG","author":"Midori","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"sayur-asem-id","country":"ID","original":"Sayur asem","title":"Sayur asem (soupe indonésienne au tamarin)","en":"Sayur asem (Indonesian tamarind vegetable soup)","es":"Sayur asem (sopa indonesia de verduras y tamarindo)","desc":"Soupe indonésienne acidulée de légumes au tamarin; adaptation aux légumes disponibles en Amérique du Nord.","cat":"Soupe","diff":"easy","prep":20,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Sayur_asem","auth":"adapted","ing":[["Maïs",2,"épis",null],["Haricots verts",200,"g",null],["Chayotte",1,null,"ou courgette"],["Arachides crues",60,"g",null],["Échalotes",3,null,null],["Ail",2,"gousses",null],["Galanga",20,"g",null],["Jus de tamarin",3,"c. à soupe",null],["Sucre de palme",1,"c. à soupe",null],["Eau",1400,"ml",null],["Sel",0.75,"c. à thé",null]],"steps":["Hacher échalotes et ail. Couper le maïs en tronçons de 2 pouces et la chayotte pelée en cubes.","Porter eau, échalotes, ail et galanga écrasé au frémissement. Ajouter arachides et maïs, puis cuire 15 minutes.","Ajouter chayotte et haricots; cuire encore 10 à 12 minutes, jusqu’à légumes tendres.","Incorporer tamarin, sucre et sel. Goûter pour équilibrer acidité et douceur.","Retirer le galanga dur et servir chaud; les morceaux de maïs se mangent séparément du bouillon."],"photo":{"file":"File:Sayur asem vegetable soup.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/58/Sayur_asem_vegetable_soup.jpg","page":"https://commons.wikimedia.org/wiki/File:Sayur_asem_vegetable_soup.jpg","author":"Sakurai Midori","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"ayam-taliwang-id","country":"ID","original":"Ayam taliwang","title":"Ayam taliwang (poulet épicé de Lombok)","en":"Ayam taliwang (Lombok spicy chicken)","es":"Ayam taliwang (pollo picante de Lombok)","desc":"Poulet de tradition sasak, associé à Lombok, rôti puis badigeonné d’une pâte aux piments.","cat":"Plat principal","diff":"medium","prep":30,"cook":50,"serv":4,"reference":"https://en.wikipedia.org/wiki/Ayam_taliwang","auth":"adapted","ing":[["Poulet entier",1300,"g",null],["Piments rouges",4,null,null],["Échalotes",5,null,null],["Ail",4,"gousses",null],["Tomates",2,null,null],["Pâte de crevettes",0.5,"c. à thé",null],["Sucre de palme",1,"c. à soupe",null],["Jus de lime",2,"c. à soupe",null],["Huile",2,"c. à soupe",null],["Sel",0.75,"c. à thé",null]],"steps":["Ouvrir le poulet en crapaudine et l’éponger. Saler et arroser de lime; réfrigérer 30 minutes.","Mixer piments, échalotes, ail et tomates. Cuire dans l’huile avec pâte de crevettes et sucre 10 minutes, jusqu’à pâte épaisse.","Badigeonner le poulet de la moitié de la pâte et le rôtir à 200 °C 35 minutes.","Ajouter le reste de pâte avec un pinceau propre puis poursuivre 10 à 15 minutes, jusqu’à poulet à 74 °C dans la cuisse sans toucher l’os.","Laisser reposer 10 minutes et découper. Adapter le nombre de piments selon la force désirée."],"place":{"slug":"id-lombok","name":"Lombok","type":"island","lat":-8.565,"lng":116.352,"summary":"Île indonésienne associée au poulet ayam taliwang."},"photo":{"file":"File:Ayam bakar khas Taliwang 2.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Ayam_bakar_khas_Taliwang_2.JPG/500px-Ayam_bakar_khas_Taliwang_2.JPG","page":"https://commons.wikimedia.org/wiki/File:Ayam_bakar_khas_Taliwang_2.JPG","author":"Midori","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"serabi-id","country":"ID","original":"Serabi","title":"Serabi (petites crêpes indonésiennes à la coco)","en":"Serabi (Indonesian coconut pancakes)","es":"Serabi (tortitas indonesias de coco)","desc":"Crêpes indonésiennes de farine de riz et lait de coco; version simple servie avec sirop de sucre de palme.","cat":"Dessert","diff":"medium","prep":20,"cook":20,"serv":12,"reference":"https://en.wikipedia.org/wiki/Serabi","auth":"adapted","ing":[["Farine de riz",200,"g",null],["Farine de blé",40,"g",null],["Lait de coco",300,"ml",null],["Eau pour pâte",120,"ml",null],["Levure sèche",3,"g",null],["Sucre",20,"g",null],["Sel",0.5,"c. à thé",null],["Sucre de palme",120,"g",null],["Eau pour sirop",150,"ml",null],["Feuille de pandan",1,null,"facultative"]],"steps":["Mélanger les farines, levure, sucre et sel. Ajouter lait de coco tiédi et eau; fouetter puis laisser reposer 45 minutes.","Faire fondre le sucre de palme dans l’eau du sirop avec pandan si disponible; mijoter 5 minutes et réserver.","Chauffer une petite poêle antiadhésive à feu doux. Verser une petite louche de pâte.","Couvrir et cuire 3 à 5 minutes sans retourner, jusqu’à dessus pris et dessous doré; répéter avec le reste.","Servir tiède avec le sirop. Cette adaptation utilise une poêle plutôt que le moule en terre traditionnel."],"photo":{"file":"File:Serabi-01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Serabi-01.jpg","page":"https://commons.wikimedia.org/wiki/File:Serabi-01.jpg","author":"Ivan Lanin","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"pinakbet-ph","country":"PH","original":"Pinakbet","title":"Pinakbet (légumes philippins mijotés)","en":"Pinakbet (Filipino vegetable stew)","es":"Pinakbet (guiso filipino de verduras)","desc":"Mijoté philippin de légumes et bagoong; adaptation avec courge, aubergine, gombo et haricots.","cat":"Plat principal","diff":"easy","prep":25,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Pinakbet","auth":"adapted","ing":[["Courge",400,"g",null],["Aubergine",1,null,null],["Gombo",150,"g",null],["Haricots verts",200,"g",null],["Tomates",3,null,null],["Oignon",1,null,null],["Ail",3,"gousses",null],["Poitrine de porc",200,"g",null],["Bagoong",1.5,"c. à soupe",null],["Eau",250,"ml",null],["Huile",1,"c. à soupe",null]],"steps":["Couper porc et courge en cubes, aubergine en demi-rondelles, et préparer les autres légumes.","Dorer le porc dans l’huile 5 minutes. Ajouter oignon et ail hachés, puis tomates; cuire 5 minutes.","Ajouter bagoong, eau et courge; couvrir et mijoter 10 minutes.","Incorporer aubergine, gombo et haricots, puis cuire 10 à 12 minutes jusqu’à légumes tendres et porc à 71 °C.","Remuer doucement pour garder les morceaux entiers. Goûter avant de saler, car le bagoong est concentré; servir avec riz."],"photo":{"file":"File:Pinakbet.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Pinakbet.JPG/500px-Pinakbet.JPG","page":"https://commons.wikimedia.org/wiki/File:Pinakbet.JPG","author":"BrokenSphere","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"sisig-ph","country":"PH","original":"Sisig","title":"Sisig au porc (adaptation philippine)","en":"Pork sisig (Filipino home adaptation)","es":"Sisig de cerdo (adaptación filipina)","desc":"Adaptation du sisig philippin au porc désossé, oignon, piment et calamansi; les recettes traditionnelles utilisent souvent d’autres morceaux.","cat":"Plat principal","diff":"medium","prep":25,"cook":60,"serv":4,"reference":"https://en.wikipedia.org/wiki/Sisig","auth":"adapted","ing":[["Poitrine de porc",600,"g",null],["Oignon rouge",1,null,null],["Piments",2,null,null],["Jus de calamansi",3,"c. à soupe","ou lime"],["Sauce soja",2,"c. à soupe",null],["Ail",3,"gousses",null],["Huile",1,"c. à soupe",null],["Poivre",0.5,"c. à thé",null],["Sel",0.5,"c. à thé",null]],"steps":["Mijoter le porc dans l’eau avec le sel et les gousses d’ail 40 minutes jusqu’à tendreté.","Égoutter, éponger puis rôtir sous le gril du four environ 10 minutes, en retournant pour colorer les deux faces.","Laisser tiédir et hacher le porc finement au couteau.","Chauffer l’huile dans une poêle et faire revenir le porc avec moitié de l’oignon haché 5 minutes; ajouter soja et piments.","Hors du feu, ajouter calamansi, poivre et oignon restant. Servir immédiatement, idéalement dans une poêle chaude."],"photo":{"file":"File:Authentic Kapampangan Sisig.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Authentic_Kapampangan_Sisig.jpg/500px-Authentic_Kapampangan_Sisig.jpg","page":"https://commons.wikimedia.org/wiki/File:Authentic_Kapampangan_Sisig.jpg","author":"Joy L. Cruz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"puto-ph","country":"PH","original":"Puto","title":"Puto (petits gâteaux philippins vapeur)","en":"Puto (Filipino steamed cakes)","es":"Puto (pastelitos filipinos al vapor)","desc":"Petits gâteaux philippins vapeur; adaptation à la farine de riz sans fermentation longue.","cat":"Dessert","diff":"medium","prep":20,"cook":20,"serv":12,"reference":"https://en.wikipedia.org/wiki/Puto","auth":"adapted","ing":[["Farine de riz",200,"g",null],["Sucre",100,"g",null],["Lait",220,"ml",null],["Eau",100,"ml",null],["Poudre à pâte",2,"c. à thé",null],["Blancs d’œufs",2,null,null],["Huile",1,"c. à soupe",null],["Sel",0.25,"c. à thé",null],["Cheddar",50,"g","facultatif, en fines lamelles"]],"steps":["Mélanger farine de riz, sucre, poudre à pâte et sel. Ajouter lait, eau et huile, puis fouetter.","Monter les blancs en neige souple et les incorporer délicatement.","Huiler 12 petits moules résistants à la chaleur et les remplir aux trois quarts. Déposer une lamelle de fromage sur chaque gâteau, si désiré, comme sur la photo.","Cuire dans un panier vapeur au-dessus d’une eau frémissante 15 à 20 minutes; envelopper le couvercle d’un linge pour retenir les gouttes.","Vérifier un gâteau avec un cure-dent puis laisser tiédir 5 minutes avant de démouler."],"photo":{"file":"File:Puto (Filipino rice cake) with cheese.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Puto_%28Filipino_rice_cake%29_with_cheese.jpg/500px-Puto_%28Filipino_rice_cake%29_with_cheese.jpg","page":"https://commons.wikimedia.org/wiki/File:Puto_(Filipino_rice_cake)_with_cheese.jpg","author":"Obsidian Soul","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"bibingka-ph","country":"PH","original":"Bibingka","title":"Bibingka (gâteau philippin de riz à la coco)","en":"Bibingka (Filipino coconut rice cake)","es":"Bibingka (pastel filipino de arroz y coco)","desc":"Gâteau philippin à farine de riz et lait de coco; adaptation au four domestique, avec feuille de bananier facultative.","cat":"Dessert","diff":"easy","prep":20,"cook":30,"serv":8,"reference":"https://en.wikipedia.org/wiki/Bibingka","auth":"adapted","ing":[["Farine de riz",200,"g",null],["Farine de riz gluant",50,"g",null],["Sucre",120,"g",null],["Lait de coco",300,"ml",null],["Œufs",3,null,null],["Beurre",60,"g",null],["Poudre à pâte",2,"c. à thé",null],["Fromage doux râpé",60,"g",null],["Noix de coco râpée",40,"g",null],["Sel",0.25,"c. à thé",null]],"steps":["Chemiser un moule de 8 pouces de papier cuisson ou de feuille de bananier lavée et assouplie brièvement à la chaleur.","Mélanger les farines, sucre, poudre à pâte et sel. Ajouter lait de coco, œufs et 40 g de beurre fondu.","Verser dans le moule et parsemer de fromage.","Cuire à 180 °C 25 à 30 minutes, jusqu’à centre pris et cure-dent sans pâte crue.","Badigeonner de beurre restant et ajouter la noix de coco. Servir tiède, en précisant que l’œuf salé traditionnel n’est pas utilisé dans cette adaptation."],"photo":{"file":"File:Philippine Dessert Bibingka Galapong.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/df/Philippine_Dessert_Bibingka_Galapong.jpg","page":"https://commons.wikimedia.org/wiki/File:Philippine_Dessert_Bibingka_Galapong.jpg","author":"Tomwsulcer","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"kuih-seri-muka-my","country":"MY","original":"Kuih seri muka","title":"Kuih seri muka (carrés malais riz gluant et pandan)","en":"Kuih seri muka (Malaysian sticky rice and pandan squares)","es":"Kuih seri muka (cuadrados malasios de arroz y pandan)","desc":"Dessert malais à deux couches : riz gluant à la coco puis crème verte au pandan.","cat":"Dessert","diff":"medium","prep":35,"cook":55,"serv":16,"reference":"https://en.wikipedia.org/wiki/Kuih_seri_muka","auth":"adapted","ing":[["Riz gluant",300,"g",null],["Lait de coco pour riz",250,"ml",null],["Sel",0.5,"c. à thé",null],["Œufs",3,null,null],["Sucre",150,"g",null],["Lait de coco pour crème",300,"ml",null],["Farine de blé",60,"g",null],["Fécule de maïs",25,"g",null],["Jus de pandan",100,"ml",null]],"steps":["Tremper le riz 4 heures puis égoutter. Le mélanger avec lait de coco du riz et sel dans un plat résistant à la chaleur.","Cuire à la vapeur 25 minutes. Remuer puis tasser fermement dans un moule de 8 pouces.","Fouetter œufs, sucre, lait de coco de crème, farine, fécule et pandan. Filtrer pour enlever les grumeaux.","Verser doucement sur le riz chaud. Cuire à vapeur douce 25 à 30 minutes, avec un couvercle protégé d’un linge, jusqu’à crème prise sans forte ébullition.","Refroidir complètement puis réfrigérer 2 heures. Couper avec un couteau légèrement huilé."],"photo":{"file":"File:Seri Muka1.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Seri_Muka1.JPG/500px-Seri_Muka1.JPG","page":"https://commons.wikimedia.org/wiki/File:Seri_Muka1.JPG","author":"SimonLyall","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"roti-john-my","country":"MY","original":"Roti john","title":"Roti john (sandwich malais aux œufs et viande)","en":"Roti john (Malaysian egg and meat sandwich)","es":"Roti john (bocadillo malasio de huevo y carne)","desc":"Sandwich aux œufs et viande courant en Malaisie et à Singapour; rattachement malais sans revendiquer une invention exclusivement locale.","cat":"Plat principal","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Roti_john","auth":"adapted","ing":[["Petites baguettes",2,null,null],["Bœuf haché",250,"g",null],["Œufs",4,null,null],["Oignon",1,null,null],["Curry en poudre",1,"c. à thé",null],["Huile",2,"c. à soupe",null],["Sauce chili",4,"c. à soupe",null],["Mayonnaise",2,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Concombre",0.5,null,null]],"steps":["Cuire le bœuf avec la moitié de l’huile et l’oignon haché, jusqu’à viande à 71 °C. Ajouter curry et sel, puis laisser tiédir.","Couper les baguettes en deux dans la longueur sans séparer entièrement leurs moitiés.","Battre les œufs et y incorporer la viande tiédie. Chauffer le reste d’huile dans une grande poêle.","Déposer une bande de mélange aux œufs puis presser une baguette ouverte dessus, mie vers le bas. Cuire 3 à 4 minutes jusqu’à œufs pris.","Retourner pour réchauffer la croûte. Garnir de sauce chili, mayonnaise et concombre, puis couper chaque sandwich en deux portions."],"photo":{"file":"File:Roti John - served.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a7/Roti_John_-_served.jpg","page":"https://commons.wikimedia.org/wiki/File:Roti_John_-_served.jpg","author":"stef yau from Seattle, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"ayam-percik-my","country":"MY","original":"Ayam percik","title":"Ayam percik (poulet malais au lait de coco)","en":"Ayam percik (Malaysian coconut grilled chicken)","es":"Ayam percik (pollo malasio a la coco)","desc":"Poulet malais rôti et nappé d’une sauce au lait de coco, citronnelle et piment.","cat":"Plat principal","diff":"medium","prep":25,"cook":45,"serv":4,"reference":"https://www.kara.com.my/recipes/ayam-percik-kelantan/","auth":"adapted","ing":[["Cuisses de poulet",4,null,null],["Lait de coco",400,"ml",null],["Échalotes",4,null,null],["Ail",3,"gousses",null],["Gingembre",20,"g",null],["Citronnelle",2,"tiges",null],["Piments rouges",2,null,null],["Jus de tamarin",2,"c. à soupe",null],["Sucre de palme",1,"c. à soupe",null],["Sel",0.75,"c. à thé",null],["Huile",1,"c. à soupe",null]],"steps":["Mixer échalotes, ail, gingembre, partie tendre de citronnelle et piments avec un peu de lait de coco.","Cuire cette pâte dans l’huile 5 minutes. Ajouter reste du lait de coco, tamarin, sucre et sel; mijoter 10 minutes pour épaissir.","Disposer le poulet dans un plat et badigeonner avec une partie de la sauce. Réserver le reste à part, sans contact avec le poulet cru.","Rôtir à 200 °C 35 à 45 minutes, jusqu’à poulet à 74 °C; ajouter de la sauce avec un pinceau propre vers la fin.","Laisser reposer 5 minutes et servir avec la sauce réservée réchauffée."],"photo":{"file":"File:Ayam Percik.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Ayam_Percik.jpg/500px-Ayam_Percik.jpg","page":"https://commons.wikimedia.org/wiki/File:Ayam_Percik.jpg","author":"Unilokman25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chilli-crab-sg","country":"SG","original":"Chilli crab","title":"Chilli crab (crabe singapourien en sauce)","en":"Chilli crab (Singaporean chilli crab)","es":"Chilli crab (cangrejo de Singapur en salsa picante)","desc":"Crabe singapourien dans une sauce tomate-piment légèrement sucrée, liée avec de l’œuf; adaptation avec crabe déjà cuit.","cat":"Plat principal","diff":"medium","prep":25,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Chilli_crab","auth":"adapted","ing":[["Crabe cuit en morceaux",1200,"g",null],["Tomates concassées",300,"g",null],["Ketchup",80,"g",null],["Échalotes",3,null,null],["Ail",4,"gousses",null],["Gingembre",20,"g",null],["Piments rouges",2,null,null],["Eau",250,"ml",null],["Sucre",1,"c. à soupe",null],["Sauce soja",1,"c. à soupe",null],["Fécule",1,"c. à soupe",null],["Œuf",1,null,null],["Huile",2,"c. à soupe",null]],"steps":["Nettoyer les morceaux de crabe cuit et casser légèrement les pinces pour permettre à la sauce de pénétrer.","Mixer échalotes, ail, gingembre et piments; cuire dans l’huile 5 minutes.","Ajouter tomates, ketchup, eau, sucre et soja, puis mijoter 8 minutes.","Ajouter le crabe et réchauffer à couvert 5 minutes. Délayer la fécule dans un peu d’eau et l’incorporer.","Verser l’œuf battu en filet et remuer jusqu’à cuisson complète. Servir avec pain vapeur ou riz, préparés séparément."],"photo":{"file":"File:Chilli Crab.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Chilli_Crab.JPG/500px-Chilli_Crab.JPG","page":"https://commons.wikimedia.org/wiki/File:Chilli_Crab.JPG","author":"Terence Ong","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"Wikimedia Commons"}},{"slug":"rabo-de-toro-es","country":"ES","original":"Rabo de toro","title":"Rabo de toro (queue de bœuf mijotée espagnole)","en":"Rabo de toro (Spanish braised oxtail)","es":"Rabo de toro guisado","desc":"Mijoté espagnol de queue de bœuf au vin et légumes, associé notamment à Cordoue.","cat":"Plat principal","diff":"medium","prep":25,"cook":210,"serv":6,"reference":"https://www.cofradiarabodetorocordobes.es/index.php/organigrama/","auth":"adapted","ing":[["Queue de bœuf",1500,"g",null],["Oignons",2,null,null],["Carottes",3,null,null],["Tomates",3,null,null],["Ail",4,"gousses",null],["Vin rouge",400,"ml",null],["Bouillon",600,"ml",null],["Huile d’olive",3,"c. à soupe",null],["Farine",30,"g",null],["Laurier",2,"feuilles",null],["Sel",1,"c. à thé",null],["Poivre",0.5,"c. à thé",null]],"steps":["Saler, poivrer et fariner légèrement les morceaux de queue. Les dorer dans l’huile par petites fournées.","Faire revenir oignons, carottes et ail hachés 8 minutes, puis ajouter tomates et cuire 5 minutes.","Remettre la viande, verser vin et bouillon, ajouter laurier et porter au frémissement.","Couvrir et mijoter à feu très doux 3 à 3 heures 30, jusqu’à viande se détachant facilement de l’os; ajouter du bouillon si nécessaire.","Retirer le laurier. Réduire la sauce à découvert si elle est liquide, rectifier l’assaisonnement et servir."],"place":"es-cordoba","photo":{"file":"File:Rabo de toro.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/ce/Rabo_de_toro.jpg","page":"https://commons.wikimedia.org/wiki/File:Rabo_de_toro.jpg","author":"Javier Lastras from España/Spain","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"gazpachuelo-es","country":"ES","original":"Gazpachuelo","title":"Gazpachuelo (soupe malaguène au poisson et mayonnaise)","en":"Gazpachuelo (Malaga fish and mayonnaise soup)","es":"Gazpachuelo malagueño","desc":"Soupe de Malaga au poisson et pommes de terre, liée avec mayonnaise hors du feu pour préserver l’émulsion.","cat":"Soupe","diff":"medium","prep":25,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Gazpachuelo","auth":"adapted","ing":[["Poisson blanc",500,"g",null],["Pommes de terre",500,"g",null],["Bouillon de poisson",1200,"ml",null],["Mayonnaise du commerce",150,"g","aux œufs pasteurisés"],["Jus de citron",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Poivre",0.25,"c. à thé",null],["Crevettes décortiquées",150,"g",null]],"steps":["Peler les pommes de terre et les couper en cubes. Les cuire dans le bouillon frémissant 18 à 20 minutes.","Ajouter le poisson en morceaux et pocher 5 à 7 minutes, jusqu’à opaque et se défaisant facilement. Ajouter les crevettes pendant les 3 dernières minutes, jusqu’à chair opaque.","Retirer la casserole du feu et laisser refroidir quelques minutes; le liquide ne doit plus bouillir.","Mettre la mayonnaise dans un bol et y fouetter plusieurs louches de bouillon tiédi, une à une.","Verser doucement ce mélange dans la soupe en remuant. Ajouter citron et assaisonnement; servir immédiatement sans refaire bouillir."],"place":{"slug":"es-malaga","name":"Malaga","type":"city","lat":36.7213,"lng":-4.4214,"summary":"Ville andalouse associée au gazpachuelo."},"photo":{"file":"File:Gazpachuelo.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/52/Gazpachuelo.jpg","page":"https://commons.wikimedia.org/wiki/File:Gazpachuelo.jpg","author":"Juan Mejuto","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"gheymeh-ir","country":"IR","original":"Gheymeh","title":"Gheymeh (mijoté iranien aux pois cassés)","en":"Gheymeh (Iranian split pea and beef stew)","es":"Gheymeh (guiso iraní de ternera y guisantes partidos)","desc":"Mijoté iranien de bœuf, pois cassés jaunes et citron noir, servi avec frites fines.","cat":"Plat principal","diff":"medium","prep":25,"cook":100,"serv":4,"reference":"https://en.wikipedia.org/wiki/Gheymeh","auth":"adapted","ing":[["Bœuf à braiser",500,"g",null],["Pois cassés jaunes",150,"g",null],["Oignon",1,null,null],["Concentré de tomate",2,"c. à soupe",null],["Citrons noirs séchés",2,null,null],["Pommes de terre",400,"g",null],["Huile pour mijoté",2,"c. à soupe",null],["Huile pour frites",500,"ml",null],["Curcuma",1,"c. à thé",null],["Cannelle",0.25,"c. à thé",null],["Eau",1000,"ml",null],["Sel",0.75,"c. à thé",null]],"steps":["Rincer et tremper les pois cassés 1 heure. Piquer les citrons noirs et les tremper 15 minutes.","Dorer oignon haché et viande en cubes dans l’huile du mijoté. Ajouter curcuma et concentré, remuer 2 minutes.","Verser l’eau, ajouter pois cassés et citrons noirs, puis mijoter 75 à 90 minutes, jusqu’à viande tendre et pois cuits mais encore reconnaissables.","Couper les pommes de terre en fines allumettes, bien les sécher et les frire à 175 °C jusqu’à dorure.","Saler le mijoté, ajouter cannelle et retirer les citrons si l’acidité est suffisante. Servir avec les frites sur le dessus et du riz préparé séparément."],"photo":{"file":"File:Gheymeh Stew.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Gheymeh_Stew.jpg/500px-Gheymeh_Stew.jpg","page":"https://commons.wikimedia.org/wiki/File:Gheymeh_Stew.jpg","author":"Sina Salimi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"tahchin-ir","country":"IR","original":"Tahchin","title":"Tahchin au poulet (riz iranien moulé au safran)","en":"Chicken tahchin (Iranian saffron rice cake)","es":"Tahchin de pollo (arroz iraní moldeado con azafrán)","desc":"Riz iranien au yaourt, œufs et safran, cuit en moule pour une croûte dorée; adaptation au poulet.","cat":"Plat principal","diff":"medium","prep":35,"cook":75,"serv":6,"reference":"https://en.wikipedia.org/wiki/Tahchin","auth":"adapted","ing":[["Riz basmati",400,"g",null],["Poulet désossé",500,"g",null],["Yaourt nature épais",250,"g",null],["Jaunes d’œufs",3,null,null],["Safran",0.2,"g",null],["Beurre",50,"g",null],["Huile",3,"c. à soupe",null],["Oignon",1,null,null],["Bouillon",500,"ml",null],["Sel",1,"c. à thé",null],["Épine-vinette séchée",30,"g","facultative"]],"steps":["Pocher le poulet avec oignon et bouillon environ 20 minutes, jusqu’à 74 °C; effilocher et réserver. Infuser le safran dans 3 cuillères de bouillon chaud.","Précuire le riz rincé dans l’eau salée 5 à 6 minutes, puis égoutter.","Mélanger yaourt, jaunes, safran et huile, puis incorporer le riz délicatement.","Beurrer généreusement un moule de 9 pouces. Tasser moitié du riz, ajouter poulet puis riz restant; couvrir d’aluminium.","Cuire à 190 °C 60 à 75 minutes jusqu’à dessous bien doré. Reposer 10 minutes, démouler et décorer si désiré d’épine-vinette brièvement sautée au beurre."],"photo":{"file":"File:Tahchin (1).JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Tahchin_%281%29.JPG/500px-Tahchin_%281%29.JPG","page":"https://commons.wikimedia.org/wiki/File:Tahchin_(1).JPG","author":"Maahmaah","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"fatteh-lb","country":"LB","original":"Fatteh","title":"Fatteh libanaise aux pois chiches","en":"Lebanese chickpea fatteh","es":"Fatteh libanés de garbanzos","desc":"Assemblage levantin très présent au Liban de pain croustillant, pois chiches et yaourt à l’ail et tahini. Le plat est partagé entre plusieurs cuisines levantines; la photo montre une présentation palestinienne aux amandes.","cat":"Plat principal","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Fatteh","auth":"adapted","ing":[["Pois chiches cuits",500,"g",null],["Pains pita",2,null,null],["Yaourt nature",400,"g",null],["Tahini",2,"c. à soupe",null],["Ail",2,"gousses",null],["Jus de citron",1,"c. à soupe",null],["Amandes",30,"g",null],["Beurre",20,"g",null],["Huile d’olive",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null]],"steps":["Couper les pitas en morceaux, huiler légèrement et griller au four à 190 °C 8 à 10 minutes jusqu’à croustillants.","Réchauffer les pois chiches avec 100 ml d’eau; garder quelques cuillères de ce liquide.","Mélanger yaourt, tahini, ail écrasé, citron et sel; détendre avec un peu du liquide tiédi, sans faire bouillir le yaourt.","Dorer les amandes fendues dans le beurre 2 minutes en surveillant.","Assembler pain, pois chiches puis sauce et amandes juste avant de servir, pour garder une partie du pain croustillante."],"photo":{"file":"File:Palestinian Hummus Fatteh.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Palestinian_Hummus_Fatteh.jpg/500px-Palestinian_Hummus_Fatteh.jpg","page":"https://commons.wikimedia.org/wiki/File:Palestinian_Hummus_Fatteh.jpg","author":"Uwe a","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"meghli-lb","country":"LB","original":"Meghli","title":"Meghli (crème libanaise épicée au riz)","en":"Meghli (Lebanese spiced rice pudding)","es":"Meghli (crema libanesa de arroz especiada)","desc":"Dessert libanais à farine de riz, carvi et cannelle, sans lait, garni de coco et noix.","cat":"Dessert","diff":"easy","prep":15,"cook":25,"serv":6,"reference":"https://en.wikipedia.org/wiki/Meghli","auth":"adapted","ing":[["Farine de riz",80,"g",null],["Eau",1000,"ml",null],["Sucre",120,"g",null],["Carvi moulu",1.5,"c. à thé",null],["Cannelle",1,"c. à thé",null],["Anis moulu",0.5,"c. à thé",null],["Noix de coco râpée",30,"g",null],["Pistaches",30,"g",null],["Amandes",30,"g",null],["Noix",30,"g",null]],"steps":["Mélanger à froid farine de riz, sucre et épices avec l’eau pour éliminer les grumeaux.","Chauffer à feu moyen en remuant continuellement jusqu’à épaississement.","Baisser le feu et cuire encore 15 à 20 minutes en remuant souvent, jusqu’à crème homogène.","Répartir dans six coupes et laisser tiédir, puis réfrigérer au moins 3 heures.","Parsemer coco et noix hachées juste avant de servir pour garder leur texture."],"photo":{"file":"File:Мигли с добавками.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/%D0%9C%D0%B8%D0%B3%D0%BB%D0%B8_%D1%81_%D0%B4%D0%BE%D0%B1%D0%B0%D0%B2%D0%BA%D0%B0%D0%BC%D0%B8.JPG/500px-%D0%9C%D0%B8%D0%B3%D0%BB%D0%B8_%D1%81_%D0%B4%D0%BE%D0%B1%D0%B0%D0%B2%D0%BA%D0%B0%D0%BC%D0%B8.JPG","page":"https://commons.wikimedia.org/wiki/File:%D0%9C%D0%B8%D0%B3%D0%BB%D0%B8_%D1%81_%D0%B4%D0%BE%D0%B1%D0%B0%D0%B2%D0%BA%D0%B0%D0%BC%D0%B8.JPG","author":"حسين علي قرياني","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"aloo-gosht-pk","country":"PK","original":"Aloo gosht","title":"Aloo gosht (mijoté pakistanais d’agneau et pommes de terre)","en":"Aloo gosht (Pakistani lamb and potato stew)","es":"Aloo gosht (guiso pakistaní de cordero y patata)","desc":"Mijoté de viande et pommes de terre très présent au Pakistan et dans d’autres cuisines d’Asie du Sud; version à l’agneau.","cat":"Plat principal","diff":"medium","prep":25,"cook":100,"serv":4,"reference":"https://en.wikipedia.org/wiki/Aloo_gosht","auth":"adapted","ing":[["Agneau à braiser",700,"g",null],["Pommes de terre",600,"g",null],["Oignons",2,null,null],["Tomates",3,null,null],["Ail",4,"gousses",null],["Gingembre",25,"g",null],["Huile",3,"c. à soupe",null],["Cumin",1,"c. à thé",null],["Coriandre moulue",1,"c. à thé",null],["Curcuma",0.5,"c. à thé",null],["Piment moulu",0.5,"c. à thé",null],["Garam masala",1,"c. à thé",null],["Eau",600,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Dorer les oignons émincés dans l’huile 10 minutes. Ajouter ail et gingembre hachés, puis viande en cubes.","Ajouter tomates, cumin, coriandre, curcuma, piment et sel. Cuire 8 minutes en remuant.","Verser l’eau et mijoter à couvert 60 à 75 minutes, jusqu’à viande presque tendre.","Ajouter pommes de terre en morceaux et poursuivre 20 à 25 minutes, jusqu’à tendreté.","Incorporer garam masala et ajuster le jus selon la consistance désirée. Servir avec riz ou pain plat."],"photo":{"file":"File:Aaloo Gosht.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Aaloo_Gosht.JPG/500px-Aaloo_Gosht.JPG","page":"https://commons.wikimedia.org/wiki/File:Aaloo_Gosht.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"zarda-pk","country":"PK","original":"Zarda","title":"Zarda (riz pakistanais sucré au safran)","en":"Zarda (Pakistani sweet saffron rice)","es":"Zarda (arroz dulce pakistaní con azafrán)","desc":"Riz sucré d’Asie du Sud très présent au Pakistan, parfumé au safran, cardamome et noix.","cat":"Dessert","diff":"medium","prep":20,"cook":35,"serv":6,"reference":"https://en.wikipedia.org/wiki/Zarda_%28food%29","auth":"adapted","ing":[["Riz basmati",250,"g",null],["Sucre",150,"g",null],["Ghee",40,"g",null],["Eau pour sirop",120,"ml",null],["Safran",0.15,"g",null],["Cardamome",4,"gousses",null],["Raisins secs",50,"g",null],["Amandes",40,"g",null],["Pistaches",30,"g",null]],"steps":["Rincer et tremper le riz 30 minutes. Infuser le safran dans 2 cuillères d’eau chaude prélevées sur l’eau du sirop.","Précuire le riz dans beaucoup d’eau 6 à 7 minutes, jusqu’à presque tendre, puis égoutter.","Chauffer le ghee, ajouter cardamome légèrement écrasée, raisins et noix pendant 1 minute.","Ajouter sucre, eau restante et safran; faire frémir pour dissoudre le sucre, puis incorporer le riz.","Couvrir et cuire à feu très doux 15 minutes. Laisser reposer 10 minutes puis égrener délicatement; servir tiède."],"photo":{"file":"File:Shahi Zarda.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Shahi_Zarda.JPG/500px-Shahi_Zarda.JPG","page":"https://commons.wikimedia.org/wiki/File:Shahi_Zarda.JPG","author":"Miansari66","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"mango-pudding-cn","country":"CN","original":"Mango pudding","title":"Mango pudding (dessert chinois à la mangue)","en":"Mango pudding (Chinese mango dessert)","es":"Mango pudding (postre chino de mango)","desc":"Dessert froid à la mangue, particulièrement associé aux tables de Hong Kong; adaptation au lait de coco.","cat":"Dessert","diff":"easy","prep":20,"cook":5,"serv":6,"reference":"https://en.wikipedia.org/wiki/Mango_pudding","auth":"adapted","ing":[["Purée de mangue",450,"g",null],["Lait de coco",200,"ml",null],["Eau",100,"ml",null],["Sucre",60,"g",null],["Gélatine en poudre",8,"g",null],["Jus de lime",1,"c. à soupe",null]],"steps":["Saupoudrer la gélatine sur la moitié de l’eau froide et laisser gonfler 5 minutes.","Chauffer l’eau restante avec le sucre jusqu’à dissolution, couper le feu et ajouter la gélatine hydratée.","Mélanger purée de mangue, lait de coco et lime, puis incorporer le sirop encore tiède.","Verser dans six petits moules ou coupes et réfrigérer au moins 4 heures jusqu’à prise.","Servir en coupe ou démouler brièvement après avoir trempé le fond du moule dans l’eau tiède."],"photo":{"file":"File:Mango pudding.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Mango_pudding.JPG/500px-Mango_pudding.JPG","page":"https://commons.wikimedia.org/wiki/File:Mango_pudding.JPG","author":"Terence","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"Wikimedia Commons"}},{"slug":"nasu-dengaku-jp","country":"JP","original":"Nasu dengaku","title":"Nasu dengaku (aubergines japonaises au miso)","en":"Nasu dengaku (Japanese miso-glazed eggplant)","es":"Nasu dengaku (berenjenas japonesas con miso)","desc":"Aubergines japonaises rôties et glacées au miso sucré, servies en accompagnement.","cat":"Accompagnement","diff":"easy","prep":15,"cook":25,"serv":4,"reference":"https://www.justonecookbook.com/miso-dengaku/","auth":"adapted","ing":[["Aubergines",2,null,null],["Miso",3,"c. à soupe",null],["Mirin",2,"c. à soupe",null],["Sucre",1,"c. à soupe",null],["Eau",2,"c. à soupe",null],["Huile",2,"c. à soupe",null],["Sésame",1,"c. à thé",null]],"steps":["Couper les aubergines en deux dans la longueur et quadriller leur chair sans percer la peau.","Badigeonner d’huile et rôtir chair dessus à 200 °C 20 à 25 minutes, jusqu’à tendreté complète.","Pendant ce temps, chauffer doucement miso, mirin, sucre et eau 2 minutes en remuant.","Étaler la sauce sur la chair cuite et passer sous le gril 2 à 3 minutes en surveillant pour éviter de brûler le sucre.","Parsemer de sésame et servir chaud ou tiède."],"photo":{"file":"File:Jin Kichi, Hampstead, London (3955079167).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Jin_Kichi%2C_Hampstead%2C_London_%283955079167%29.jpg/500px-Jin_Kichi%2C_Hampstead%2C_London_%283955079167%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Jin_Kichi,_Hampstead,_London_(3955079167).jpg","author":"Ewan Munro from London, UK","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"tsukune-jp","country":"JP","original":"Tsukune","title":"Tsukune (brochettes japonaises de poulet)","en":"Tsukune (Japanese chicken meatball skewers)","es":"Tsukune (brochetas japonesas de pollo)","desc":"Boulettes japonaises de poulet sur brochettes, laquées avec une sauce soja et mirin. Les tsukune sont les boulettes sur la brochette de droite; la photo présente aussi une autre brochette de poulet.","cat":"Plat principal","diff":"medium","prep":25,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Tsukune","auth":"adapted","ing":[["Poulet haché",500,"g",null],["Oignon vert",2,null,null],["Gingembre",15,"g",null],["Œuf",1,null,null],["Panko",40,"g",null],["Sauce soja",3,"c. à soupe",null],["Mirin",3,"c. à soupe",null],["Sucre",1,"c. à soupe",null],["Eau",2,"c. à soupe",null],["Huile",1,"c. à soupe",null]],"steps":["Mélanger poulet, oignons verts hachés, gingembre râpé, œuf et panko. Réfrigérer 20 minutes.","Former 12 boulettes ovales et les enfiler sur des brochettes adaptées à la cuisson; tremper les brochettes en bois au préalable.","Faire frémir soja, mirin, sucre et eau 5 minutes pour obtenir une sauce légèrement nappante.","Cuire les brochettes dans une poêle huilée ou sur un gril, en les retournant, 10 à 12 minutes jusqu’à poulet à 74 °C.","Badigeonner de sauce avec un pinceau propre en fin de cuisson et faire légèrement caraméliser sans brûler. Servir avec la sauce restante réchauffée."],"photo":{"file":"File:Seseri and Tsukune.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Seseri_and_Tsukune.jpg/500px-Seseri_and_Tsukune.jpg","page":"https://commons.wikimedia.org/wiki/File:Seseri_and_Tsukune.jpg","author":"ayustety from Tokyo, Japan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"gyeran-mari-kr","country":"KR","original":"Gyeran mari","title":"Gyeran-mari (omelette coréenne roulée)","en":"Gyeran-mari (Korean rolled omelette)","es":"Gyeran-mari (tortilla coreana enrollada)","desc":"Omelette coréenne salée roulée avec carotte et oignons verts, distincte du tamagoyaki japonais sucré. L’omelette est visible en haut de la photographie, accompagnée d’autres plats.","cat":"Accompagnement","diff":"medium","prep":15,"cook":10,"serv":4,"reference":"https://en.wikipedia.org/wiki/Gyeran-mari","auth":"adapted","ing":[["Œufs",6,null,null],["Carotte",50,"g",null],["Oignons verts",2,null,null],["Lait",1,"c. à soupe",null],["Huile",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null]],"steps":["Hacher très finement carotte et oignons verts pour éviter qu’ils déchirent les couches.","Battre les œufs avec lait et sel, puis incorporer les légumes.","Huiler une poêle antiadhésive à feu moyen doux et verser une fine couche de mélange.","Quand elle est presque prise, la rouler vers un bord. Huiler légèrement l’espace libre, ajouter une autre couche et poursuivre le roulage; répéter jusqu’à épuisement.","Cuire le rouleau sur ses faces pour terminer la cuisson des œufs. Reposer 3 minutes puis trancher à 1/2 pouce."],"photo":{"file":"File:Korean cuisine-Gyeranmari, Kimchi stew, Myeolchi bokkeum.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Korean_cuisine-Gyeranmari%2C_Kimchi_stew%2C_Myeolchi_bokkeum.jpg/500px-Korean_cuisine-Gyeranmari%2C_Kimchi_stew%2C_Myeolchi_bokkeum.jpg","page":"https://commons.wikimedia.org/wiki/File:Korean_cuisine-Gyeranmari,_Kimchi_stew,_Myeolchi_bokkeum.jpg","author":"Jens Ohlig","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"gyeran-jjim-kr","country":"KR","original":"Gyeran jjim","title":"Gyeran-jjim (œufs coréens vapeur)","en":"Gyeran-jjim (Korean steamed eggs)","es":"Gyeran-jjim (huevos coreanos al vapor)","desc":"Préparation coréenne d’œufs moelleux cuits doucement avec bouillon; adaptation en bol au panier vapeur.","cat":"Accompagnement","diff":"easy","prep":10,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Gyeran-jjim","auth":"adapted","ing":[["Œufs",4,null,null],["Bouillon de légumes",250,"ml",null],["Oignon vert",1,null,null],["Huile de sésame",1,"c. à thé",null],["Sel",0.5,"c. à thé",null]],"steps":["Battre les œufs avec bouillon tiédi et sel, sans produire beaucoup de mousse.","Filtrer dans un bol résistant à la chaleur légèrement huilé; retirer les bulles visibles.","Couvrir le bol et le placer dans un panier vapeur au-dessus d’eau frémissante.","Cuire à vapeur douce 12 à 15 minutes, jusqu’à centre pris mais moelleux; prolonger légèrement si le bol est profond.","Ajouter oignon vert émincé et un filet d’huile de sésame. Servir immédiatement."],"photo":{"file":"File:Korean.Banchan-Gyeran.jjim-01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Korean.Banchan-Gyeran.jjim-01.jpg/500px-Korean.Banchan-Gyeran.jjim-01.jpg","page":"https://commons.wikimedia.org/wiki/File:Korean.Banchan-Gyeran.jjim-01.jpg","author":"stuart_spivack (a flickr user)","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"gamjajeon-kr","country":"KR","original":"Gamjajeon","title":"Gamjajeon (galettes coréennes de pommes de terre)","en":"Gamjajeon (Korean potato pancakes)","es":"Gamjajeon (tortitas coreanas de patata)","desc":"Galettes coréennes de pommes de terre râpées et leur fécule, sans œuf; une technique différente des galettes polonaises ou allemandes.","cat":"Accompagnement","diff":"easy","prep":25,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Gamja-jeon","auth":"adapted","ing":[["Pommes de terre",700,"g",null],["Oignon",0.5,null,null],["Huile",3,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Sauce soja",2,"c. à soupe",null],["Vinaigre de riz",1,"c. à soupe",null],["Oignon vert",1,null,null]],"steps":["Peler et râper finement les pommes de terre et l’oignon. Égoutter dans une passoire au-dessus d’un bol, sans jeter le jus tout de suite.","Laisser le jus reposer 10 minutes, verser le liquide clair et récupérer la fécule déposée au fond.","Mélanger pommes de terre, fécule récupérée et sel.","Former 8 petites galettes dans une poêle huilée à feu moyen. Cuire 4 à 5 minutes par face jusqu’à croustillantes et cuites au centre.","Mélanger soja, vinaigre et oignon vert haché pour une sauce à tremper; servir les galettes sans attendre."],"photo":{"file":"File:Korean potato pancake-Gamjajeon-01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Korean_potato_pancake-Gamjajeon-01.jpg","page":"https://commons.wikimedia.org/wiki/File:Korean_potato_pancake-Gamjajeon-01.jpg","author":"User:Opencage","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"Wikimedia Commons"}},{"slug":"bindaetteok-kr","country":"KR","original":"Bindaetteok","title":"Bindaetteok (galettes coréennes de haricots mungo)","en":"Bindaetteok (Korean mung bean pancakes)","es":"Bindaetteok (tortitas coreanas de judías mungo)","desc":"Galettes coréennes de mungo décortiqué, kimchi, germes et porc; la pâte ne repose pas sur la farine de blé.","cat":"Plat principal","diff":"medium","prep":30,"cook":20,"serv":4,"reference":"https://en.wikipedia.org/wiki/Bindae-tteok","auth":"adapted","ing":[["Haricots mungo décortiqués",250,"g",null],["Eau",180,"ml",null],["Kimchi",150,"g",null],["Germes de haricots",150,"g",null],["Porc haché",150,"g",null],["Oignons verts",3,null,null],["Huile",4,"c. à soupe",null],["Sel",0.5,"c. à thé",null]],"steps":["Tremper les haricots mungo 4 heures, rincer et égoutter. Blanchir les germes 2 minutes puis bien les égoutter.","Mixer les mungo avec l’eau pour une pâte légèrement granuleuse.","Ajouter kimchi haché, germes, porc, oignons verts et sel; mélanger pour répartir la farce.","Faire 8 galettes dans une poêle généreusement huilée à feu moyen et cuire 4 à 5 minutes par face.","Vérifier que le porc atteint 71 °C et la pâte est cuite au centre. Égoutter légèrement et servir croustillant."],"photo":{"file":"File:Korean.food-Bindaetteok-01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/fa/Korean.food-Bindaetteok-01.jpg","page":"https://commons.wikimedia.org/wiki/File:Korean.food-Bindaetteok-01.jpg","author":"jetalone (a flickr user)","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}}]$batch$::jsonb);
